    '    l_feature_rows pls_integer;',
    '    l_feature_on   pls_integer;',
    '    l_mapped       pls_integer;',
    'begin',
    '    if :P0_DOMAIN_ID is null then return false; end if;',
    '    select count(*), count(case when type_2 = ''AIOPS'' and status = ''ACTIVE'' then 1 end)',
    '      into l_feature_rows, l_feature_on',
    '      from kbot_apex_platform_config',
    '     where type_1 = ''PLATFORM_FEATURE'';',
    '    if l_feature_rows > 0 and l_feature_on = 0 then return false; end if;',
    '    select count(*) into l_mapped',
    '      from kbot_app_domain',
    '     where app_id = ''aiops'' and domain_id = :P0_DOMAIN_ID and status = ''ACTIVE'';',
    '    return l_mapped > 0 and (kbot_apex_auth.is_platform_admin(:APP_USER) or kbot_apex_auth.has_permission(''aiops:use''));',
    'end;')))).to_clob
