prompt --application/shared_components/logic/application_processes/kbot_ensure_page_app_context
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(48464910184834501)
,p_process_sequence=>5
,p_process_point=>'BEFORE_HEADER'
,p_process_name=>'KBOT_ENSURE_PAGE_APP_CONTEXT'
,p_static_id=>'kbot-ensure-page-app-context'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_page_id number := apex_application.g_flow_step_id;',
'    l_requested_domain_id number;',
'    l_nav_permissions varchar2(32767);',
'begin',
'    if regexp_like(v(''P0_DOMAIN_ID''), ''^\d+$'') then',
'        l_requested_domain_id := to_number(v(''P0_DOMAIN_ID''));',
'    end if;',
'',
'    -- Page 21 activates the AIOps context in the client before',
'    -- navigation.  The shared package still carries the legacy',
'    -- Page 21 mapping, so invoking ensure_page_context here can',
'    -- replace the explicit AIOps Domain with the user preference.',
'    -- Preserve the requested global Domain; the workspace then',
'    -- validates and refreshes the AIOps context in place.',
'    if l_page_id <> 21 then',
'        kbot_apex_auth.ensure_page_context(',
'            p_page_id => l_page_id,',
'            p_requested_domain_id => l_requested_domain_id,',
'            p_agent_scope => ''aiops''',
'        );',
'    end if;',
'',
'    if l_requested_domain_id is not null then',
'        select listagg(permission_code, ''|'')',
'                   within group (order by permission_code)',
'          into l_nav_permissions',
'          from (',
'                select distinct rp.permission_code',
'                  from kbot_app_member_role mr',
'                  join kbot_app_member m',
'                    on m.app_id = mr.app_id',
'                   and m.user_id = mr.user_id',
'                   and m.status = ''ACTIVE''',
'                  join kbot_platform_app a',
'                    on a.app_id = mr.app_id',
'                   and a.app_id = ''aiops''',
'                   and a.status = ''ACTIVE''',
'                  join kbot_app_domain ad',
'                    on ad.app_id = mr.app_id',
'                   and ad.domain_id = l_requested_domain_id',
'                   and ad.status = ''ACTIVE''',
'                  join kbot_platform_user u',
'                    on u.user_id = mr.user_id',
'                   and u.status = ''ACTIVE''',
'                  join kbot_app_role r',
'                    on r.app_id = mr.app_id',
'                   and r.role_code = mr.role_code',
'                   and r.status = ''ACTIVE''',
'                  join kbot_app_role_permission rp',
'                    on rp.app_id = r.app_id',
'                   and rp.role_code = r.role_code',
'                 where mr.user_id = :APP_USER',
'                   and mr.status = ''ACTIVE''',
'                   and (',
'                       mr.scope_mode = ''ALL_APP_DOMAINS''',
'                       or exists (',
'                           select 1',
'                             from kbot_app_member_role_scope s',
'                            where s.app_id = mr.app_id',
'                              and s.user_id = mr.user_id',
'                              and s.role_code = mr.role_code',
'                              and s.domain_id = l_requested_domain_id',
'                       )',
'                   )',
'               );',
'    end if;',
'',
'    apex_util.set_session_state(''P0_NAV_PERMISSION_CODES'', l_nav_permissions);',
'    apex_authorization.reset_cache;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
);
end;
/
prompt --application/shared_components/logic/application_processes/kbot_load_auth_context
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(48464829309834501)
,p_process_sequence=>10
,p_process_point=>'AFTER_LOGIN'
,p_process_name=>'KBOT_LOAD_AUTH_CONTEXT'
,p_static_id=>'kbot-load-auth-context'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_token        varchar2(4000);',
'    l_display_name varchar2(256);',
'    l_domain_id    varchar2(64);',
'    l_domain_name  varchar2(256);',
'    l_force_change varchar2(5);',
'    l_permissions  varchar2(32767);',
'    l_entry_kind  varchar2(16);',
'    l_app_id      varchar2(64);',
'    l_expires_at  varchar2(128);',
'    l_preferred_domain_id number :=',
'        coalesce(',
'        case',
'            when regexp_like(',
'                apex_util.get_preference(',
'                    ''KBOT_DOMAIN_APP_'' || v(''APP_ID''),',
'                    :APP_USER',
'                ),',
'                ''^\d+$''',
'            ) then to_number(',
'                apex_util.get_preference(',
'                    ''KBOT_DOMAIN_APP_'' || v(''APP_ID''),',
'                    :APP_USER',
'                )',
'            )',
'        end,',
'        kbot_apex_auth.preferred_domain_id(:APP_USER)',
'    );',
'    l_requested_domain_id number;',
'    l_is_platform_admin VARCHAR2(1) :=',
'        CASE',
'            WHEN kbot_apex_auth.is_platform_admin(:APP_USER) THEN ''Y''',
'            ELSE ''N''',
'        END;',
'',
'    function app_enabled(',
'        p_app_id          in varchar2,',
'        p_feature_code    in varchar2,',
'        p_permission_code in varchar2',
'    ) return varchar2 is',
'        l_feature_rows pls_integer;',
'        l_feature_on   pls_integer;',
'        l_access       pls_integer;',
'    begin',
'        select count(*),',
'               count(case when type_2 = p_feature_code and status = ''ACTIVE'' then 1 end)',
'          into l_feature_rows, l_feature_on',
'          from kbot_apex_platform_config',
'         where type_1 = ''PLATFORM_FEATURE'';',
'        if l_feature_rows > 0 and l_feature_on = 0 then',
'            return ''N'';',
'        end if;',
'',
'        select count(*) into l_access',
'          from kbot_app_member_role mr',
'          join kbot_platform_user u on u.user_id = mr.user_id and u.status = ''ACTIVE''',
'          join kbot_app_role r on r.app_id = mr.app_id and r.role_code = mr.role_code and r.status = ''ACTIVE''',
'          join kbot_app_role_permission rp on rp.app_id = mr.app_id and rp.role_code = mr.role_code',
'         where mr.app_id = p_app_id',
'           and (mr.scope_mode = ''ALL_APP_DOMAINS'' or exists (',
'               select 1 from kbot_app_member_role_scope s',
'                where s.app_id = mr.app_id and s.user_id = mr.user_id',
'                  and s.role_code = mr.role_code and s.domain_id = to_number(l_domain_id)',
'           ))',
'           and mr.user_id = :APP_USER',
'           and mr.status = ''ACTIVE''',
'           and (p_permission_code is null or rp.permission_code = p_permission_code);',
'        return case when l_access > 0 then ''Y'' else ''N'' end;',
'    end app_enabled;',
'begin',
'    select c001, c002, c003, c004, c005, c006, c007, c008',
'      into l_token,',
'           l_display_name,',
'           l_domain_id,',
'           l_domain_name,',
'           l_force_change,',
'           l_entry_kind,',
'           l_app_id,',
'           l_expires_at',
'      from apex_collections',
'     where collection_name = ''KBOT_AUTH_CONTEXT''',
'       and seq_id = 1;',
'',
'    -- A user can authenticate through the platform entry while only',
'    -- holding application roles.  Resolve an initial authorized',
'    -- domain before feature flags are calculated, otherwise the',
'    -- dashboard is rendered with an empty domain and all app',
'    -- features disabled.',
'    if l_entry_kind = ''PLATFORM'' then',
'        l_requested_domain_id := case',
'            when regexp_like(l_domain_id, ''^\d+$'') then to_number(l_domain_id)',
'        end;',
'        l_domain_id := null;',
'        l_domain_name := null;',
'        begin',
'            WITH enabled_domain_apps AS (',
'                SELECT ad.domain_id,',
'                       ad.app_id',
'                  FROM kbot_app_domain ad',
'                  JOIN kbot_platform_app a',
'                    ON a.app_id = ad.app_id',
'                   AND a.status = ''ACTIVE''',
'                 WHERE ad.status = ''ACTIVE''',
'                   AND ad.app_id = ''aiops''',
'                   AND (',
'                       NOT EXISTS (',
'                           SELECT 1',
'                             FROM kbot_apex_platform_config feature_config',
'                            WHERE feature_config.type_1 = ''PLATFORM_FEATURE''',
'                       )',
'                       OR EXISTS (',
'                           SELECT 1',
'                             FROM kbot_apex_platform_config enabled_feature',
'                            WHERE enabled_feature.type_1 = ''PLATFORM_FEATURE''',
'                              AND enabled_feature.status = ''ACTIVE''',
'                              AND enabled_feature.type_2 = ''AIOPS''',
'                       )',
'                   )',
'            )',
'            SELECT domain_id, domain_name',
'              INTO l_domain_id, l_domain_name',
'              FROM (',
'                    SELECT d.domain_id,',
'                           d.name AS domain_name,',
'                           d.created_at',
'                      FROM kbot_platform_domain d',
'                     WHERE d.status = ''ACTIVE''',
'                       AND (',
'                           (',
'                               l_is_platform_admin = ''Y''',
'                               AND EXISTS (',
'                                   SELECT 1',
'                                     FROM enabled_domain_apps admin_eda',
'                                    WHERE admin_eda.domain_id = d.domain_id',
'                               )',
'                           )',
'                           OR EXISTS (',
'                               SELECT 1',
'                                 FROM enabled_domain_apps eda',
'                                 JOIN kbot_app_member_role mr',
'                                   ON mr.app_id = eda.app_id',
'                                  AND mr.user_id = :APP_USER',
'                                  AND mr.status = ''ACTIVE''',
'                                 JOIN kbot_app_member m',
'                                   ON m.app_id = mr.app_id',
'                                  AND m.user_id = mr.user_id',
'                                  AND m.status = ''ACTIVE''',
'                                 JOIN kbot_app_role r',
'                                   ON r.app_id = mr.app_id',
'                                  AND r.role_code = mr.role_code',
'                                  AND r.status = ''ACTIVE''',
'                                 JOIN kbot_app_role_permission rp',
'                                   ON rp.app_id = mr.app_id',
'                                  AND rp.role_code = mr.role_code',
unistr('                                  -- \4EFB\4E00\6709\6548\5E94\7528\6743\9650\90FD\53EF\5EFA\7ACB\8BE5\5E94\7528\7684\521D\59CB Domain \4E0A\4E0B\6587\FF1B'),
unistr('                                  -- \7BA1\7406\7C7B\89D2\8272\4E0D\5E94\88AB\9519\8BEF\8981\6C42\989D\5916\62E5\6709 app:use\3002'),
'                                  AND rp.permission_code LIKE mr.app_id || '':%''',
'                                WHERE eda.domain_id = d.domain_id',
'                                  AND (',
'                                      mr.scope_mode = ''ALL_APP_DOMAINS''',
'                                      OR EXISTS (',
'                                          SELECT 1',
'                                            FROM kbot_app_member_role_scope s',
'                                           WHERE s.app_id = mr.app_id',
'                                             AND s.user_id = mr.user_id',
'                                             AND s.role_code = mr.role_code',
'                                             AND s.domain_id = d.domain_id',
'                                      )',
'                                  )',
'                           )',
'                       )',
'                     ORDER BY CASE',
'                                  WHEN d.domain_id = l_requested_domain_id THEN 0',
'                                  WHEN d.domain_id = l_preferred_domain_id THEN 1',
'                                  ELSE 2',
'                              END,',
'                              d.domain_id DESC',
'                   )',
'             WHERE rownum = 1;',
'        EXCEPTION',
'            WHEN no_data_found THEN',
'                NULL;',
'        END;',
'    end if;',
'',
unistr('    -- \767B\5F55\521D\59CB\5316\5B8C\6210\540E\7ACB\5373\6536\655B\5931\6548\504F\597D\FF0C\907F\514D\65E7\6388\6743\65E5\540E\91CD\65B0\751F\6548\3002'),
'    IF l_entry_kind = ''PLATFORM'' THEN',
'        IF regexp_like(l_domain_id, ''^\d+$'') THEN',
'            apex_util.set_preference(',
'                p_preference => ''KBOT_DOMAIN_APP_'' || v(''APP_ID''),',
'                p_value      => l_domain_id,',
'                p_user       => :APP_USER',
'            );',
'        ELSE',
'            apex_util.remove_preference(',
'                p_preference => ''KBOT_DOMAIN_APP_'' || v(''APP_ID''),',
'                p_user       => :APP_USER',
'            );',
'        END IF;',
'    END IF;',
'',
'    apex_util.set_session_state(''P0_USER_TOKEN'', l_token);',
'    apex_util.set_session_state(''P0_AUTH_ENTRY_KIND'', l_entry_kind);',
'    apex_util.set_session_state(''P0_AUTH_APP_ID'', l_app_id);',
'    apex_util.set_session_state(''P0_AUTH_EXPIRES_AT'', l_expires_at);',
'    apex_util.set_session_state(''P0_DOMAIN_ID'', l_domain_id);',
'    apex_util.set_session_state(''P0_AUTH_DISPLAY_NAME'', l_display_name);',
'    apex_util.set_session_state(''P0_AUTH_DOMAIN_NAME'', l_domain_name);',
'    apex_util.set_session_state(',
'        ''P0_AUTH_MUST_CHANGE_PASSWORD'',',
'        l_force_change',
'    );',
'    select listagg(permission_code, ''|'') within group (order by permission_code)',
'      into l_permissions',
'      from (',
'            select p.permission_code',
'              from kbot_permission p',
'             where l_entry_kind = ''PLATFORM''',
'               and p.permission_code like ''platform:%''',
'               and kbot_apex_auth.is_platform_admin(:APP_USER)',
'            union',
'            select distinct rp.permission_code',
'              from kbot_platform_user_role ur',
'              join kbot_platform_user u on u.user_id = ur.user_id and u.status = ''ACTIVE''',
'              join kbot_app_role r on r.app_id = ''platform'' and r.role_code = ur.role_code and r.status = ''ACTIVE''',
'              join kbot_app_role_permission rp on rp.app_id = r.app_id and rp.role_code = r.role_code',
'             where ur.user_id = :APP_USER',
'               and ur.status = ''ACTIVE''',
'            union',
'            select distinct rp.permission_code',
'              from kbot_app_member_role mr',
'              join kbot_app_member m',
'                on m.app_id = mr.app_id',
'               and m.user_id = mr.user_id',
'               and m.status = ''ACTIVE''',
'              join kbot_platform_app a',
'                on a.app_id = mr.app_id',
'               and a.status = ''ACTIVE''',
'              join kbot_app_domain ad',
'                on ad.app_id = mr.app_id',
'               and ad.domain_id = to_number(l_domain_id)',
'               and ad.status = ''ACTIVE''',
'              join kbot_platform_user u on u.user_id = mr.user_id and u.status = ''ACTIVE''',
'              join kbot_app_role r on r.app_id = mr.app_id and r.role_code = mr.role_code and r.status = ''ACTIVE''',
'              join kbot_app_role_permission rp on rp.app_id = mr.app_id and rp.role_code = mr.role_code',
'             where (',
'                   l_entry_kind = ''PLATFORM''',
'                   or (',
'                       l_entry_kind = ''BUSINESS''',
'                       and mr.app_id = l_app_id',
'                   )',
'               )',
'               and (mr.scope_mode = ''ALL_APP_DOMAINS'' or exists (',
'                   select 1 from kbot_app_member_role_scope s',
'                    where s.app_id = mr.app_id and s.user_id = mr.user_id',
'                      and s.role_code = mr.role_code and s.domain_id = to_number(l_domain_id)',
'               ))',
'               and mr.user_id = :APP_USER',
'               and mr.status = ''ACTIVE''',
'           );',
'    apex_util.set_session_state(''P0_PERMISSION_CODES'', l_permissions);',
'    apex_util.set_session_state(',
'        ''P0_FEATURE_AIOPS'',',
'        app_enabled(''aiops'', ''AIOPS'', null)',
'    );',
'    apex_authorization.reset_cache;',
'    apex_collection.delete_collection(''KBOT_AUTH_CONTEXT'');',
'exception',
'    when no_data_found then',
'        null;',
'end;'))
,p_process_clob_language=>'PLSQL'
);
end;
/
prompt --application/shared_components/logic/application_processes/kbot_sso_acquire_context
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(48465249590834501)
,p_process_sequence=>9
,p_process_point=>'ON_DEMAND'
,p_process_name=>'KBOT_SSO_ACQUIRE_CONTEXT'
,p_static_id=>'kbot-sso-acquire-context'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_domain_id number;',
'    l_result    kbot_apex_auth.t_context;',
'begin',
'    if regexp_like(apex_application.g_x02, ''^\d+$'') then',
'        l_domain_id := to_number(apex_application.g_x02);',
'    end if;',
'    -- Acquire a validated short-lived App token without replacing',
'    -- the page''s global PLATFORM/BUSINESS authorization context.',
'    -- Diagnostic and future cross-app readers can therefore reuse',
'    -- the common SSO implementation without contaminating menus.',
'    kbot_apex_auth.acquire_app_context(',
'        p_target_app => apex_application.g_x01,',
'        p_requested_domain_id => l_domain_id,',
'        p_result => l_result,',
'        p_apply_context => false',
'    );',
'    apex_json.open_object;',
'    apex_json.write(''activated'', l_result.status = ''READY'');',
'    apex_json.write(''status'', l_result.status);',
'    apex_json.write(''code'', l_result.result_code);',
'    apex_json.write(''message'', l_result.message);',
'    apex_json.write(''entry_kind'', l_result.entry_kind);',
'    apex_json.write(''app_id'', l_result.app_id);',
'    apex_json.write(''domain_id'', l_result.domain_id);',
'    apex_json.write(''domain_name'', l_result.domain_name);',
'    apex_json.write(''access_token'', l_result.access_token);',
'    apex_json.write(''expires_at'', l_result.expires_at);',
'    apex_json.write(''permission_codes'', l_result.permission_codes);',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
);
end;
/
prompt --application/shared_components/logic/application_processes/kbot_sso_activate_context
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(48465191582834501)
,p_process_sequence=>8
,p_process_point=>'ON_DEMAND'
,p_process_name=>'KBOT_SSO_ACTIVATE_CONTEXT'
,p_static_id=>'kbot-sso-activate-context'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_domain_id        number;',
'    l_result           kbot_apex_auth.t_context;',
'    l_live_permissions varchar2(32767);',
'begin',
'    if regexp_like(apex_application.g_x02, ''^\d+$'') then',
'        l_domain_id := to_number(apex_application.g_x02);',
'    end if;',
'    kbot_apex_auth.acquire_app_context(',
'        p_target_app => apex_application.g_x01,',
'        p_requested_domain_id => l_domain_id,',
'        p_result => l_result,',
'        p_apply_context => true',
'    );',
'    if l_result.status = ''READY'' then',
'        select listagg(permission_code, ''|'') within group (order by permission_code)',
'          into l_live_permissions',
'          from (',
'                select p.permission_code',
'                  from kbot_permission p',
'                 where kbot_apex_auth.is_platform_admin(:APP_USER)',
'                   and (',
'                       p.permission_code like ''platform:%''',
'                       or (',
'                           l_result.entry_kind = ''BUSINESS''',
'                           and l_result.app_id is not null',
'                           and p.permission_code like lower(l_result.app_id) || '':%''',
'                       )',
'                   )',
'                union',
'                select distinct rp.permission_code',
'                  from kbot_platform_user_role ur',
'                  join kbot_platform_user u',
'                    on u.user_id = ur.user_id',
'                   and u.status = ''ACTIVE''',
'                  join kbot_app_role r',
'                    on r.app_id = ''platform''',
'                   and r.role_code = ur.role_code',
'                   and r.status = ''ACTIVE''',
'                  join kbot_app_role_permission rp',
'                    on rp.app_id = r.app_id',
'                   and rp.role_code = r.role_code',
'                 where ur.user_id = :APP_USER',
'                   and ur.status = ''ACTIVE''',
'                union',
'                select distinct rp.permission_code',
'                  from kbot_app_member_role mr',
'                  join kbot_platform_user u',
'                    on u.user_id = mr.user_id',
'                   and u.status = ''ACTIVE''',
'                  join kbot_app_role r',
'                    on r.app_id = mr.app_id',
'                   and r.role_code = mr.role_code',
'                   and r.status = ''ACTIVE''',
'                  join kbot_app_role_permission rp',
'                    on rp.app_id = r.app_id',
'                   and rp.role_code = r.role_code',
'                 where l_result.entry_kind = ''BUSINESS''',
'                   and mr.app_id = lower(l_result.app_id)',
'                   and mr.user_id = :APP_USER',
'                   and mr.status = ''ACTIVE''',
'                   and (',
'                       mr.scope_mode = ''ALL_APP_DOMAINS''',
'                       or exists (',
'                           select 1',
'                             from kbot_app_member_role_scope s',
'                            where s.app_id = mr.app_id',
'                              and s.user_id = mr.user_id',
'                              and s.role_code = mr.role_code',
'                              and s.domain_id = l_result.domain_id',
'                       )',
'                   )',
'               );',
'        l_result.permission_codes := l_live_permissions;',
'        apex_util.set_session_state(''P0_PERMISSION_CODES'', l_live_permissions);',
'        apex_authorization.reset_cache;',
'    end if;',
'    apex_json.open_object;',
'    apex_json.write(''activated'', l_result.status = ''READY'');',
'    apex_json.write(''status'', l_result.status);',
'    apex_json.write(''code'', l_result.result_code);',
'    apex_json.write(''message'', l_result.message);',
'    apex_json.write(''entry_kind'', l_result.entry_kind);',
'    apex_json.write(''app_id'', l_result.app_id);',
'    apex_json.write(''domain_id'', l_result.domain_id);',
'    apex_json.write(''domain_name'', l_result.domain_name);',
'    apex_json.write(''access_token'', l_result.access_token);',
'    apex_json.write(''expires_at'', l_result.expires_at);',
'    apex_json.write(''permission_codes'', l_result.permission_codes);',
'    apex_json.open_array(''domain_options'');',
'    if l_result.status = ''DOMAIN_REQUIRED'' then',
'        for d in (',
'            select to_number(c003) domain_id, c004 domain_name',
'              from apex_collections',
'             where collection_name = ''KBOT_SSO_ENTRIES''',
'               and c001 = lower(trim(apex_application.g_x01))',
'             order by to_number(c003) desc',
'        ) loop',
'            apex_json.open_object;',
'            apex_json.write(''domain_id'', d.domain_id);',
'            apex_json.write(''domain_name'', d.domain_name);',
'            apex_json.close_object;',
'        end loop;',
'    end if;',
'    apex_json.close_array;',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
);
end;
/
prompt --application/shared_components/logic/application_processes/p0_accept_auth_token
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(48465539855834501)
,p_process_sequence=>12
,p_process_point=>'ON_DEMAND'
,p_process_name=>'P0_ACCEPT_AUTH_TOKEN'
,p_static_id=>'p0-accept-auth-token'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_base_url     varchar2(4000);',
'    l_response     clob;',
'    l_user_id      varchar2(256);',
'    l_display_name varchar2(256);',
'    l_domain_id    number;',
'    l_domain_name  varchar2(256);',
'    l_entry_kind   varchar2(16);',
'    l_app_id       varchar2(64);',
'    l_expires_at   varchar2(128) := trim(apex_application.g_x02);',
'    l_force_change varchar2(1);',
'    l_context_key  varchar2(256);',
'    l_app_name     varchar2(256);',
'begin',
'    if apex_application.g_x01 is null then',
unistr('        raise_application_error(-20001, ''\540E\53F0\672A\8FD4\56DE\66FF\6362\4EE4\724C\3002'');'),
'    end if;',
'',
'    select max(case when protocol is not null and host is not null then',
'               protocol || ''://'' || host ||',
'               case when port is not null then '':'' || to_char(port) end',
'           end)',
'      into l_base_url',
'      from kbot_apex_platform_config',
'     where type_1 = ''KBOT_SERVICE''',
'       and type_2 = ''SERVICE''',
'       and status = ''ACTIVE'';',
'    if l_base_url is null then',
'        l_base_url := rtrim(apex_util.host_url(''HOST''), ''/'');',
'    end if;',
'',
'    apex_web_service.g_request_headers.delete;',
'    apex_web_service.g_request_headers(1).name := ''Authorization'';',
'    apex_web_service.g_request_headers(1).value := ''Bearer '' || apex_application.g_x01;',
'    apex_web_service.g_request_headers(2).name := ''Accept'';',
'    apex_web_service.g_request_headers(2).value := ''application/json'';',
'    apex_web_service.g_request_headers(3).name := ''X-Request-ID'';',
'    apex_web_service.g_request_headers(3).value := lower(rawtohex(sys_guid()));',
'    l_response := apex_web_service.make_rest_request(',
'        p_url => rtrim(l_base_url, ''/'') || ''/api/v1/auth/me'',',
'        p_http_method => ''GET''',
'    );',
'    if apex_web_service.g_status_code <> 200 then',
unistr('        raise_application_error(-20001, ''\66FF\6362\4EE4\724C\6821\9A8C\5931\8D25\3002'');'),
'    end if;',
'',
'    l_user_id := json_value(l_response, ''$.user_id'');',
'    l_display_name := json_value(l_response, ''$.display_name'');',
'    l_domain_id := json_value(l_response, ''$.domain_id'' returning number);',
'    l_domain_name := coalesce(trim(apex_application.g_x03), json_value(l_response, ''$.domain_name''));',
'    l_entry_kind := upper(json_value(l_response, ''$.entry_kind''));',
'    l_app_id := lower(json_value(l_response, ''$.app_id''));',
'    l_force_change := case when lower(json_value(l_response, ''$.must_change_password'')) = ''true'' then ''Y'' else ''N'' end;',
'    if lower(trim(l_user_id)) <> lower(trim(:APP_USER))',
'       or l_entry_kind not in (''PLATFORM'', ''BUSINESS'')',
'       or l_expires_at is null',
'       or (l_entry_kind = ''PLATFORM'' and (l_app_id is not null or l_domain_id is not null))',
'       or (l_entry_kind = ''BUSINESS'' and (',
'           l_app_id <> lower(v(''P0_AUTH_APP_ID''))',
'           or l_domain_id <> to_number(v(''P0_DOMAIN_ID''))',
'       )) then',
unistr('        raise_application_error(-20001, ''\66FF\6362\4EE4\724C\4E0E\5F53\524D\767B\5F55\4E0A\4E0B\6587\4E0D\5339\914D\3002'');'),
'    end if;',
'',
'    l_context_key := case when l_entry_kind = ''PLATFORM''',
'                          then ''PLATFORM''',
'                          else l_app_id || '':'' || to_char(l_domain_id)',
'                     end;',
'    if l_entry_kind = ''PLATFORM'' then',
unistr('        l_app_name := ''\5E73\53F0\63A7\5236\53F0'';'),
'    else',
'        select max(c002)',
'          into l_app_name',
'          from apex_collections',
'         where collection_name = ''KBOT_SSO_ENTRIES''',
'           and c001 = l_app_id',
'           and c003 = to_char(l_domain_id);',
'    end if;',
'    apex_collection.delete_members(',
'        p_collection_name => ''KBOT_ENTRY_TOKENS'',',
'        p_attr_number => 1,',
'        p_attr_value => l_context_key',
'    );',
'    apex_collection.add_member(',
'        p_collection_name => ''KBOT_ENTRY_TOKENS'',',
'        p_c001 => l_context_key,',
'        p_c002 => l_entry_kind,',
'        p_c003 => l_app_id,',
'        p_c004 => to_char(l_domain_id),',
'        p_c005 => l_app_name,',
'        p_c006 => l_domain_name,',
'        p_c007 => apex_application.g_x01,',
'        p_c008 => l_display_name,',
'        p_c009 => l_force_change,',
'        p_c010 => l_expires_at',
'    );',
'',
'    apex_util.set_session_state(''P0_USER_TOKEN'', apex_application.g_x01);',
'    apex_util.set_session_state(''P0_AUTH_DISPLAY_NAME'', l_display_name);',
'    apex_util.set_session_state(''P0_AUTH_ENTRY_KIND'', l_entry_kind);',
'    apex_util.set_session_state(''P0_AUTH_APP_ID'', l_app_id);',
'    apex_util.set_session_state(''P0_AUTH_EXPIRES_AT'', l_expires_at);',
'    apex_util.set_session_state(''P0_AUTH_MUST_CHANGE_PASSWORD'', l_force_change);',
'    if l_entry_kind = ''BUSINESS'' then',
'        apex_util.set_session_state(''P0_AUTH_DOMAIN_NAME'', l_domain_name);',
'    end if;',
'    apex_json.open_object;',
'    apex_json.write(''accepted'', true);',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
);
end;
/
prompt --application/shared_components/logic/application_processes/p0_activate_app_context
begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(48465052621834501)
,p_process_sequence=>8
,p_process_point=>'ON_DEMAND'
,p_process_name=>'P0_ACTIVATE_APP_CONTEXT'
,p_static_id=>'p0-activate-app-context'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_target_app varchar2(64) := lower(trim(apex_application.g_x01));',
'    l_requested_domain number;',
'    l_base_url varchar2(4000);',
'    l_auth_response clob;',
'    l_token varchar2(4000);',
'    l_entry_kind varchar2(16);',
'    l_app_id varchar2(64);',
'    l_app_name varchar2(256);',
'    l_domain_id number;',
'    l_domain_name varchar2(256);',
'    l_display_name varchar2(256);',
'    l_force_change varchar2(1);',
'    l_expires_at varchar2(128);',
'    l_platform_token varchar2(4000);',
'    l_platform_expires_at varchar2(128);',
'    l_platform_seq number;',
'    l_permissions varchar2(32767);',
'begin',
'    if l_target_app not in (''platform'', ''aiops'') then',
unistr('        raise_application_error(-20001, ''\76EE\6807\5E94\7528\65E0\6548\3002'');'),
'    end if;',
'    if regexp_like(apex_application.g_x02, ''^\d+$'') then',
'        l_requested_domain := to_number(apex_application.g_x02);',
'    end if;',
'',
'    select max(',
'               case when protocol is not null and host is not null then',
'                   protocol || ''://'' || host ||',
'                   case when port is not null then '':'' || to_char(port) end',
'               end',
'           )',
'      into l_base_url',
'      from kbot_apex_platform_config',
'     where type_1 = ''KBOT_SERVICE''',
'       and type_2 = ''SERVICE''',
'       and status = ''ACTIVE'';',
'    if l_base_url is null then',
'        l_base_url := regexp_replace(',
'            rtrim(apex_util.host_url(''HOST''), ''/''),',
'            '':(8080|8181)$'',',
'            ''''',
'        );',
'    end if;',
'',
'    select seq_id, c007, c010',
'      into l_platform_seq, l_platform_token, l_platform_expires_at',
'      from apex_collections',
'     where collection_name = ''KBOT_ENTRY_TOKENS''',
'       and c001 = ''PLATFORM''',
'       and rownum = 1;',
'',
'    if l_platform_expires_at is null',
'       or substr(l_platform_expires_at, 1, 19) <=',
'          to_char(sys_extract_utc(systimestamp + interval ''5'' minute), ''YYYY-MM-DD"T"HH24:MI:SS'') then',
'        apex_web_service.g_request_headers.delete;',
'        apex_web_service.g_request_headers(1).name := ''Authorization'';',
'        apex_web_service.g_request_headers(1).value := ''Bearer '' || l_platform_token;',
'        apex_web_service.g_request_headers(2).name := ''Accept'';',
'        apex_web_service.g_request_headers(2).value := ''application/json'';',
'        apex_web_service.g_request_headers(3).name := ''X-Request-ID'';',
'        apex_web_service.g_request_headers(3).value := lower(rawtohex(sys_guid()));',
'        l_auth_response := apex_web_service.make_rest_request(',
'            p_url => rtrim(l_base_url, ''/'') || ''/api/v1/auth/refresh'',',
'            p_http_method => ''POST''',
'        );',
'        if apex_web_service.g_status_code <> 200',
'           or upper(json_value(l_auth_response, ''$.entry_kind'')) <> ''PLATFORM'' then',
unistr('            raise_application_error(-20002, ''\5E73\53F0\767B\5F55\5DF2\8FC7\671F\FF0C\8BF7\91CD\65B0\767B\5F55\3002'');'),
'        end if;',
'        l_platform_token := json_value(l_auth_response, ''$.access_token'');',
'        l_platform_expires_at := json_value(l_auth_response, ''$.expires_at'');',
'        apex_collection.update_member_attribute(''KBOT_ENTRY_TOKENS'', l_platform_seq, 7, l_platform_token);',
'        apex_collection.update_member_attribute(''KBOT_ENTRY_TOKENS'', l_platform_seq, 10, l_platform_expires_at);',
'    end if;',
'',
'    if l_target_app = ''platform'' then',
'        l_token := l_platform_token;',
'        l_entry_kind := ''PLATFORM'';',
'        l_app_id := null;',
unistr('        l_app_name := ''\5E73\53F0\63A7\5236\53F0'';'),
'        l_display_name := v(''P0_AUTH_DISPLAY_NAME'');',
'        l_force_change := v(''P0_AUTH_MUST_CHANGE_PASSWORD'');',
'        l_expires_at := l_platform_expires_at;',
'        if l_requested_domain is not null then',
'            select domain_id, name',
'              into l_domain_id, l_domain_name',
'              from kbot_platform_domain',
'             where domain_id = l_requested_domain',
'               and status = ''ACTIVE'';',
'        end if;',
'    else',
'        if l_requested_domain is null then',
unistr('            raise_application_error(-20003, ''\8BF7\5148\9009\62E9\6709\6548\7684\4E1A\52A1\57DF\3002'');'),
'        end if;',
'        begin',
'            select c007, c002, c003, to_number(c004), c005, c006,',
'                   c008, c009, c010',
'              into l_token, l_entry_kind, l_app_id, l_domain_id,',
'                   l_app_name, l_domain_name, l_display_name,',
'                   l_force_change, l_expires_at',
'              from (',
'                    select c007, c002, c003, c004, c005, c006,',
'                           c008, c009, c010',
'                      from apex_collections',
'                     where collection_name = ''KBOT_ENTRY_TOKENS''',
'                       and c001 = l_target_app || '':'' || to_char(l_requested_domain)',
'                       and c010 is not null',
'                       and substr(c010, 1, 19) >',
'                           to_char(sys_extract_utc(systimestamp + interval ''5'' minute), ''YYYY-MM-DD"T"HH24:MI:SS'')',
'                     order by seq_id desc',
'                   )',
'             where rownum = 1;',
'        exception',
'            when no_data_found then',
'                select max(c002), max(c004)',
'                  into l_app_name, l_domain_name',
'                  from apex_collections',
'                 where collection_name = ''KBOT_SSO_ENTRIES''',
'                   and c001 = l_target_app',
'                   and c003 = to_char(l_requested_domain);',
'                if l_app_name is null then',
unistr('                    raise_application_error(-20004, ''\5F53\524D\8D26\53F7\6CA1\6709\76EE\6807\5E94\7528 \548C\4E1A\52A1\57DF\7684\663E\5F0F\6388\6743\3002'');'),
'                end if;',
'',
'                apex_web_service.g_request_headers.delete;',
'                apex_web_service.g_request_headers(1).name := ''Authorization'';',
'                apex_web_service.g_request_headers(1).value := ''Bearer '' || l_platform_token;',
'                apex_web_service.g_request_headers(2).name := ''Content-Type'';',
'                apex_web_service.g_request_headers(2).value := ''application/json'';',
'                apex_web_service.g_request_headers(3).name := ''Accept'';',
'                apex_web_service.g_request_headers(3).value := ''application/json'';',
'                apex_web_service.g_request_headers(4).name := ''X-Request-ID'';',
'                apex_web_service.g_request_headers(4).value := lower(rawtohex(sys_guid()));',
'                l_auth_response := apex_web_service.make_rest_request(',
'                    p_url => rtrim(l_base_url, ''/'') || ''/api/v1/auth/exchange'',',
'                    p_http_method => ''POST'',',
'                    p_body => json_object(',
'                        ''app_id'' value l_target_app,',
'                        ''domain_id'' value l_requested_domain',
'                    )',
'                );',
'                if apex_web_service.g_status_code <> 200 then',
unistr('                    raise_application_error(-20005, ''\76EE\6807\5E94\7528 \514D\5BC6\4F1A\8BDD\4EA4\6362\5931\8D25\3002'');'),
'                end if;',
'                l_token := json_value(l_auth_response, ''$.access_token'');',
'                l_entry_kind := upper(json_value(l_auth_response, ''$.entry_kind''));',
'                l_app_id := lower(json_value(l_auth_response, ''$.app_id''));',
'                l_domain_id := json_value(l_auth_response, ''$.domain_id'' returning number);',
'                l_domain_name := json_value(l_auth_response, ''$.domain_name'');',
'                l_display_name := json_value(l_auth_response, ''$.display_name'');',
'                l_force_change := case when lower(json_value(l_auth_response, ''$.must_change_password'')) = ''true'' then ''Y'' else ''N'' end;',
'                l_expires_at := json_value(l_auth_response, ''$.expires_at'');',
'                if l_token is null or l_entry_kind <> ''BUSINESS''',
'                   or l_app_id <> l_target_app',
'                   or l_domain_id <> l_requested_domain',
'                   or l_expires_at is null then',
unistr('                    raise_application_error(-20006, ''\76EE\6807\5E94\7528 \4F1A\8BDD\4EA4\6362\8FD4\56DE\65E0\6548\3002'');'),
'                end if;',
'                apex_collection.delete_members(',
'                    p_collection_name => ''KBOT_ENTRY_TOKENS'',',
'                    p_attr_number => 1,',
'                    p_attr_value => l_target_app || '':'' || to_char(l_domain_id)',
'                );',
'                apex_collection.add_member(',
'                    p_collection_name => ''KBOT_ENTRY_TOKENS'',',
'                    p_c001 => l_target_app || '':'' || to_char(l_domain_id),',
'                    p_c002 => ''BUSINESS'',',
'                    p_c003 => l_target_app,',
'                    p_c004 => to_char(l_domain_id),',
'                    p_c005 => l_app_name,',
'                    p_c006 => l_domain_name,',
'                    p_c007 => l_token,',
'                    p_c008 => l_display_name,',
'                    p_c009 => l_force_change,',
'                    p_c010 => l_expires_at',
'                );',
'        end;',
'    end if;',
'',
'    apex_util.set_session_state(''P0_USER_TOKEN'', l_token);',
'    apex_util.set_session_state(''P0_AUTH_ENTRY_KIND'', l_entry_kind);',
'    apex_util.set_session_state(''P0_AUTH_APP_ID'', l_app_id);',
'    apex_util.set_session_state(''P0_DOMAIN_ID'', to_char(l_domain_id));',
'    apex_util.set_session_state(''P0_AUTH_DOMAIN_NAME'', l_domain_name);',
'    apex_util.set_session_state(''P0_AUTH_DISPLAY_NAME'', l_display_name);',
'    apex_util.set_session_state(''P0_AUTH_MUST_CHANGE_PASSWORD'', l_force_change);',
'    apex_util.set_session_state(''P0_AUTH_EXPIRES_AT'', l_expires_at);',
'    if apex_collection.collection_exists(''KBOT_AUTH_CONTEXT'') then',
'        for c in (',
'            select seq_id',
'              from apex_collections',
'             where collection_name = ''KBOT_AUTH_CONTEXT''',
'        ) loop',
'            apex_collection.update_member_attribute(''KBOT_AUTH_CONTEXT'', c.seq_id, 3, to_char(l_domain_id));',
'            apex_collection.update_member_attribute(''KBOT_AUTH_CONTEXT'', c.seq_id, 4, l_domain_name);',
'        end loop;',
'    end if;',
'    select listagg(permission_code, ''|'') within group (order by permission_code)',
'      into l_permissions',
'      from (',
'            select p.permission_code',
'              from kbot_permission p',
'             where l_entry_kind = ''PLATFORM''',
'               and p.permission_code like ''platform:%''',
'               and kbot_apex_auth.is_platform_admin(:APP_USER)',
'            union',
'            select distinct rp.permission_code',
'              from kbot_platform_user_role ur',
'              join kbot_platform_user u on u.user_id = ur.user_id and u.status = ''ACTIVE''',
'              join kbot_app_role r on r.app_id = ''platform'' and r.role_code = ur.role_code and r.status = ''ACTIVE''',
'              join kbot_app_role_permission rp on rp.app_id = r.app_id and rp.role_code = r.role_code',
'             where ur.user_id = :APP_USER',
'               and ur.status = ''ACTIVE''',
'            union',
'            select distinct rp.permission_code',
'              from kbot_app_member_role mr',
'              join kbot_platform_user u on u.user_id = mr.user_id and u.status = ''ACTIVE''',
'              join kbot_app_role r on r.app_id = mr.app_id and r.role_code = mr.role_code and r.status = ''ACTIVE''',
'              join kbot_app_role_permission rp on rp.app_id = mr.app_id and rp.role_code = mr.role_code',
'             where l_entry_kind = ''BUSINESS''',
'               and mr.app_id = l_app_id',
'               and (mr.scope_mode = ''ALL_APP_DOMAINS'' or exists (',
'                   select 1 from kbot_app_member_role_scope s',
'                    where s.app_id = mr.app_id',
'                      and s.user_id = mr.user_id',
'                      and s.role_code = mr.role_code',
'                      and s.domain_id = l_domain_id',
'               ))',
'               and mr.user_id = :APP_USER',
'               and mr.status = ''ACTIVE''',
'           );',
'    apex_util.set_session_state(''P0_PERMISSION_CODES'', l_permissions);',
'    apex_authorization.reset_cache;',
'',
'    apex_json.open_object;',
'    apex_json.write(''activated'', true);',
'    apex_json.write(''entry_kind'', l_entry_kind);',
'    apex_json.write(''app_id'', l_app_id);',
'    apex_json.write(''domain_id'', l_domain_id);',
'    apex_json.write(''domain_name'', l_domain_name);',
'    apex_json.write(''access_token'', l_token);',
'    apex_json.write(''expires_at'', l_expires_at);',
'    apex_json.write(''permission_codes'', l_permissions);',
'    apex_json.close_object;',
'exception',
'    when no_data_found then',
'        apex_json.open_object;',
'        apex_json.write(''activated'', false);',
unistr('        apex_json.write(''message'', ''\5F53\524D\8D26\53F7\6CA1\6709\76EE\6807\5E94\7528\548C\4E1A\52A1\57DF\7684\6709\6548\4F1A\8BDD\FF0C\8BF7\91CD\65B0\767B\5F55\3002'');'),
'        apex_json.close_object;',
'    when others then',
'        apex_json.open_object;',
'        apex_json.write(''activated'', false);',
'        apex_json.write(',
'            ''message'',',
'            case sqlcode',
unistr('                when -20001 then ''\76EE\6807\5E94\7528\65E0\6548\3002'''),
unistr('                when -20002 then ''\5E73\53F0\767B\5F55\5DF2\8FC7\671F\FF0C\8BF7\91CD\65B0\767B\5F55\3002'''),
unistr('                when -20003 then ''\8BF7\5148\9009\62E9\6709\6548\7684\4E1A\52A1\57DF\3002'''),
unistr('                when -20004 then ''\5F53\524D\8D26\53F7\6CA1\6709\76EE\6807\5E94\7528 \548C\4E1A\52A1\57DF\7684\663E\5F0F\6388\6743\3002'''),
unistr('                when -20005 then ''\76EE\6807\5E94\7528 \514D\5BC6\4F1A\8BDD\4EA4\6362\5931\8D25\3002'''),
unistr('                when -20006 then ''\76EE\6807\5E94\7528 \4F1A\8BDD\4EA4\6362\8FD4\56DE\65E0\6548\3002'''),
unistr('                else ''\8FDB\5165\76EE\6807\5E94\7528\5931\8D25\FF0C\8BF7\7A0D\540E\91CD\8BD5\3002'''),
'            end',
'        );',
'        apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
);
