'          join kbot_app_domain ad on ad.app_id = mr.app_id and ad.domain_id = :P0_DOMAIN_ID and ad.status = ''ACTIVE''',
'          join kbot_platform_user u on u.user_id = mr.user_id and u.status = ''ACTIVE''',
'          join kbot_app_role r on r.app_id = mr.app_id and r.role_code = mr.role_code and r.status = ''ACTIVE''',
