wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(48487168133836641)
,p_process_sequence=>30
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P10_GET_NAVIGATION_URL'
,p_static_id=>'p10-get-navigation-url'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_page_id   pls_integer;',
'    l_domain_id number;',
'    l_items     varchar2(4000);',
'    l_values    varchar2(4000);',
'    l_target_id varchar2(32);',
'    l_url       varchar2(32767);',
'begin',
'    begin l_page_id := to_number(apex_application.g_x01);',
unistr('    exception when value_error then raise_application_error(-20001, ''\76EE\6807\9875\9762\65E0\6548\3002''); end;'),
'    if l_page_id not in (15,21,47,52,53,54,56,57,58,59,65,66,68,69,70,71,72,73,75,77,78,79,81,82,83,84,101,106,107,108,109,110,111,112,113,114,115,118) then',
unistr('        raise_application_error(-20002, ''\4E0D\5141\8BB8\8DF3\8F6C\5230\8BE5\9875\9762\3002'');'),
'    end if;',
'    if l_page_id <> 85 then',
'        begin l_domain_id := to_number(nvl(nullif(trim(apex_application.g_x03), ''''), v(''P0_DOMAIN_ID'')));',
unistr('        exception when value_error then raise_application_error(-20005, ''\4E1A\52A1\57DF\65E0\6548\3002''); end;'),
unistr('        if l_domain_id is null then raise_application_error(-20003, ''\8BF7\5148\9009\62E9\4E1A\52A1\57DF\3002''); end if;'),
'        begin',
'            select domain_id into l_domain_id from kbot_platform_domain where domain_id = l_domain_id and status = ''ACTIVE'';',
unistr('        exception when no_data_found then raise_application_error(-20005, ''\4E1A\52A1\57DF\4E0D\5B58\5728\6216\5DF2\505C\7528\3002''); end;'),
'    end if;',
'    case l_page_id',
'        when 52 then l_items := ''P0_DOMAIN_ID,P52_RUN_ID''; l_values := to_char(l_domain_id)||'',''||apex_application.g_x02;',
'        when 73 then',
'            l_items := ''P0_DOMAIN_ID,P73_WORK_ITEM_ID,P73_VISIBILITY'';',
'            l_values := to_char(l_domain_id)||'',''||apex_application.g_x02||'',''||',
'                case upper(trim(apex_application.g_x04))',
'                    when ''ALL'' then ''ALL''',
'                    when ''EXCEPTIONS'' then ''EXCEPTIONS''',
'                    else ''SCOPE''',
'                end;',
'        when 58 then',
'            l_target_id := lower(replace(trim(apex_application.g_x02), ''-'', ''''));',
'            if l_target_id is null then',
'                l_items := ''P0_DOMAIN_ID'';',
'                l_values := to_char(l_domain_id);',
'            else',
'                if not regexp_like(l_target_id, ''^[0-9a-f]{32}$'') then',
unistr('                    raise_application_error(-20006, ''\8FD0\7EF4\76EE\6807\5E93 ID \65E0\6548\3002'');'),
'                end if;',
'                begin',
'                    select lower(rawtohex(target_id))',
'                      into l_target_id',
'                      from kbot_ops_target',
'                     where domain_id = l_domain_id',
'                       and lower(rawtohex(target_id)) = l_target_id;',
'                exception',
'                    when no_data_found then',
unistr('                        raise_application_error(-20007, ''\8FD0\7EF4\76EE\6807\5E93\4E0D\5B58\5728\6216\4E0D\5C5E\4E8E\5F53\524D\4E1A\52A1\57DF\3002'');'),
'                end;',
'                l_items := ''P0_DOMAIN_ID,P58_TARGET_FILTER'';',
'                l_values := to_char(l_domain_id)||'',''||l_target_id;',
'            end if;',
'        when 57 then',
'            if upper(trim(apex_application.g_x02)) = ''FAILED'' then',
'                l_items := ''P0_DOMAIN_ID,P57_VIEW,P57_STATUS'';',
'                l_values := to_char(l_domain_id)||'',RUNS,FAILED'';',
'            elsif upper(trim(apex_application.g_x02)) = ''REPORTS'' then',
'                l_items := ''P0_DOMAIN_ID,P57_VIEW'';',
'                l_values := to_char(l_domain_id)||'',REPORTS'';',
'            else',
'                l_items := ''P0_DOMAIN_ID,P57_VIEW'';',
'                l_values := to_char(l_domain_id)||'',RUNS'';',
'            end if;',
'        when 85 then null;',
'        else l_items := ''P0_DOMAIN_ID''; l_values := to_char(l_domain_id);',
'    end case;',
unistr('    if l_page_id = 52 and apex_application.g_x02 is null then raise_application_error(-20004, ''\8FD0\884C ID \4E0D\80FD\4E3A\7A7A\3002''); end if;'),
'    l_url := apex_page.get_url(p_page => l_page_id, p_clear_cache => to_char(l_page_id), p_items => l_items, p_values => l_values);',
'    apex_json.open_object; apex_json.write(''url'', l_url); apex_json.close_object;',
'exception',
'    when others then',
'        apex_json.open_object;',
'        apex_json.write(',
'            ''error'',',
'            case',
'                when sqlcode between -20099 and -20000 then regexp_replace(sqlerrm, ''^ORA-[0-9]+: *'', '''')',
unistr('                else ''\65E0\6CD5\751F\6210\76EE\6807\9875\9762\5730\5740\3002'''),
'            end',
'        );',
'        apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
,p_internal_uid=>48487168133836641
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(48487049935836641)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P10_LOAD_WORKBENCH'
,p_static_id=>'p10-load-workbench'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_domain_id                 number;',
'    l_domain_name               varchar2(256);',
'    l_is_platform_admin         boolean := kbot_apex_auth.is_platform_admin(:APP_USER);',
'    l_identity_label             varchar2(4000);',
'    l_feature_rows              pls_integer := 0;',
'    l_aiops_feature             pls_integer := 0;',
'    l_aiops_mapped              pls_integer := 0;',
'    l_aiops_authorized          boolean := false;',
'    l_aiops_available           boolean := false;',
'    l_can_aiops_use             pls_integer := 0;',
'    l_all_permissions           varchar2(32767);',
'    procedure write_aiops_app is',
'    begin',
'        apex_json.open_object;',
'        apex_json.write(''app_id'', ''aiops'');',
'        apex_json.write(''feature_enabled'', l_aiops_feature = 1);',
'        apex_json.write(''domain_mapped'', l_aiops_mapped > 0);',
'        apex_json.write(''authorized'', l_aiops_authorized);',
'        apex_json.write(''available'', l_aiops_available);',
'        apex_json.close_object;',
'    end;',
'begin',
'    begin',
'        l_domain_id := to_number(nullif(trim(v(''P0_DOMAIN_ID'')), ''''));',
'    exception',
'        when value_error then l_domain_id := null;',
'    end;',
'',
'    if l_domain_id is not null then',
'        select max(name)',
'          into l_domain_name',
'          from kbot_platform_domain',
'         where domain_id = l_domain_id',
'           and status = ''ACTIVE'';',
'    end if;',
'',
'    select listagg(permission_code, ''|'') within group (order by permission_code)',
'      into l_all_permissions',
'      from (',
'            select distinct rp.permission_code',
'              from kbot_platform_user_role ur',
'              join kbot_platform_user u',
'                on u.user_id = ur.user_id',
'               and u.status = ''ACTIVE''',
'              join kbot_app_role r',
'                on r.app_id = ''platform''',
'               and r.role_code = ur.role_code',
'               and r.status = ''ACTIVE''',
'              join kbot_app_role_permission rp',
'                on rp.app_id = r.app_id',
'               and rp.role_code = r.role_code',
'             where ur.user_id = :APP_USER',
'               and ur.status = ''ACTIVE''',
'            union',
'            select distinct rp.permission_code',
'              from kbot_app_member_role mr',
'              join kbot_app_member m',
'                on m.app_id = mr.app_id',
'               and m.user_id = mr.user_id',
'               and m.status = ''ACTIVE''',
'              join kbot_platform_app a',
'                on a.app_id = mr.app_id',
'               and a.status = ''ACTIVE''',
'              join kbot_app_domain ad',
'                on ad.app_id = mr.app_id',
'               and ad.domain_id = l_domain_id',
'               and ad.status = ''ACTIVE''',
'              join kbot_platform_user u',
'                on u.user_id = mr.user_id',
'               and u.status = ''ACTIVE''',
'              join kbot_app_role r',
'                on r.app_id = mr.app_id',
'               and r.role_code = mr.role_code',
'               and r.status = ''ACTIVE''',
'              join kbot_app_role_permission rp',
'                on rp.app_id = r.app_id',
'               and rp.role_code = r.role_code',
'             where mr.app_id = ''aiops''',
'               and mr.user_id = :APP_USER',
'               and mr.status = ''ACTIVE''',
'               and (',
'                   mr.scope_mode = ''ALL_APP_DOMAINS''',
'                   or exists (',
'                       select 1',
'                         from kbot_app_member_role_scope s',
'                        where s.app_id = mr.app_id',
'                          and s.user_id = mr.user_id',
'                          and s.role_code = mr.role_code',
'                          and s.domain_id = l_domain_id',
'                   )',
'               )',
'           );',
'',
'    if l_is_platform_admin then',
unistr('        l_identity_label := ''\5E73\53F0\7BA1\7406\5458'';'),
'    else',
unistr('        select listagg(display_name, ''\3001'') within group (order by upper(display_name), display_name)'),
'          into l_identity_label',
'          from (',
'                select distinct r.display_name',
'                  from kbot_app_member_role mr',
'                  join kbot_app_member m',
'                    on m.app_id = mr.app_id',
'                   and m.user_id = mr.user_id',
'                   and m.status = ''ACTIVE''',
'                  join kbot_platform_app a',
'                    on a.app_id = mr.app_id',
'                   and a.status = ''ACTIVE''',
'                  join kbot_app_domain ad',
'                    on ad.app_id = mr.app_id',
'                   and ad.domain_id = l_domain_id',
'                   and ad.status = ''ACTIVE''',
'                  join kbot_app_role r',
'                    on r.app_id = mr.app_id',
'                   and r.role_code = mr.role_code',
'                   and r.status = ''ACTIVE''',
'                 where mr.app_id = ''aiops''',
'                   and mr.user_id = :APP_USER',
'                   and mr.status = ''ACTIVE''',
'                   and (',
'                       mr.scope_mode = ''ALL_APP_DOMAINS''',
'                       or exists (',
'                           select 1',
'                             from kbot_app_member_role_scope rs',
'                            where rs.app_id = mr.app_id',
'                              and rs.user_id = mr.user_id',
'                              and rs.role_code = mr.role_code',
'                              and rs.domain_id = l_domain_id',
'                       )',
'                   )',
'               );',
unistr('        l_identity_label := nvl(l_identity_label, ''\65E0'');'),
'    end if;',
'',
'    select count(*),',
'           count(case when type_2 = ''AIOPS'' and status = ''ACTIVE'' then 1 end)',
'      into l_feature_rows, l_aiops_feature',
'      from kbot_apex_platform_config',
'     where type_1 = ''PLATFORM_FEATURE'';',
'    if l_feature_rows = 0 then',
'        l_aiops_feature := 1;',
'    end if;',
'',
'    if l_domain_id is not null then',
'        select count(*)',
'          into l_aiops_mapped',
'          from kbot_app_domain',
'         where domain_id = l_domain_id',
'           and app_id = ''aiops''',
'           and status = ''ACTIVE'';',
'    end if;',
'',
unistr('    l_aiops_authorized := apex_authorization.is_authorized(''AIOps\5BFC\822A\53EF\8BBF\95EE'');'),
'    l_aiops_available := l_aiops_feature = 1',
'        and l_aiops_mapped > 0',
'        and (',
'            l_is_platform_admin',
'            or regexp_like(nvl(l_all_permissions, '' ''), ''(^|\|)aiops:[^|]+($|\|)'')',
'        );',
'    if l_is_platform_admin or kbot_apex_auth.has_permission(''aiops:use'', l_all_permissions) then',
'        l_can_aiops_use := 1;',
'    end if;',
'',
'    apex_json.open_object;',
'    apex_json.write(''domain_id'', l_domain_id);',
unistr('    apex_json.write(''domain_name'', nvl(l_domain_name, ''\672A\9009\62E9\4E1A\52A1\57DF''));'),
'    apex_json.write(''is_platform_admin'', l_is_platform_admin);',
'    apex_json.write(''identity_label'', l_identity_label);',
'    apex_json.write(''generated_at'', to_char(systimestamp, ''YYYY-MM-DD"T"HH24:MI:SSTZH:TZM''));',
'    apex_json.open_object(''capabilities'');',
'    apex_json.write(''chat'', l_aiops_available and l_can_aiops_use = 1);',
'    apex_json.write(''aiops_diagnostic_source_manage'', l_is_platform_admin or kbot_apex_auth.has_permission(''aiops:diagnostic_source_manage'', l_all_permissions));',
'    apex_json.write(''aiops_target_manage'', l_is_platform_admin or kbot_apex_auth.has_permission(''aiops:target_manage'', l_all_permissions));',
'    apex_json.write(''aiops_policy_manage'', l_is_platform_admin or kbot_apex_auth.has_permission(''aiops:policy_manage'', l_all_permissions));',
'    apex_json.write(''aiops_plan_manage'', l_is_platform_admin or kbot_apex_auth.has_permission(''aiops:plan_manage'', l_all_permissions));',
'    apex_json.write(''aiops_agent_manage'', l_is_platform_admin or kbot_apex_auth.has_permission(''aiops:agent_manage'', l_all_permissions));',
'    apex_json.write(''aiops_knowledge_manage'', l_is_platform_admin or kbot_apex_auth.has_permission(''aiops:knowledge_manage'', l_all_permissions));',
'    apex_json.write(''aiops_use'', l_is_platform_admin or kbot_apex_auth.has_permission(''aiops:use'', l_all_permissions));',
'    apex_json.write(''aiops_proposal_approve'', l_is_platform_admin or kbot_apex_auth.has_permission(''aiops:proposal:approve'', l_all_permissions));',
'    apex_json.write(''aiops_member_manage'', l_is_platform_admin or kbot_apex_auth.has_permission(''aiops:member_manage'', l_all_permissions));',
'    apex_json.write(''aiops_role_manage'', l_is_platform_admin or kbot_apex_auth.has_permission(''aiops:role_manage'', l_all_permissions));',
'    apex_json.write(''aiops_api_key_manage'', l_is_platform_admin or kbot_apex_auth.has_permission(''aiops:api_key_manage'', l_all_permissions));',
'    apex_json.close_object;',
'    apex_json.open_array(''apps'');',
'    write_aiops_app;',
'    apex_json.close_array;',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
,p_internal_uid=>48487049935836641
);
end;
