,p_static_id=>'p15-get-resource-url'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_resource_type varchar2(80) := lower(apex_application.g_x01);',
'    l_resource_id   varchar2(256) := apex_application.g_x02;',
'    l_page_id       pls_integer;',
'    l_item_name     varchar2(64);',
'    l_url           varchar2(32767);',
'begin',
'    case l_resource_type',
'        when ''aiops_run_input_required'' then l_page_id := 53; l_item_name := ''P53_HITL_ID'';',
'        when ''aiops_run'' then l_page_id := 52; l_item_name := ''P52_RUN_ID'';',
'        when ''aiops_proposal'' then l_page_id := 54; l_item_name := ''P54_PROPOSAL_ID'';',
'        when ''aiops_report'' then l_page_id := 57; l_item_name := ''P57_VIEW,P57_REPORT_ID''; l_resource_id := ''REPORTS,'' || l_resource_id;',
'        when ''aiops_situation'' then l_page_id := 58; l_item_name := ''P58_SITUATION_ID'';',
unistr('        else raise_application_error(-20001, ''\5F53\524D AIOps \8D44\6E90\7C7B\578B\6CA1\6709\5BF9\5E94\9875\9762\3002'');'),
'    end case;',
'    l_url := apex_page.get_url(',
'        p_page => l_page_id, p_clear_cache => to_char(l_page_id),',
'        p_items => l_item_name, p_values => l_resource_id',
'    );',
'    apex_json.open_object;',
'    apex_json.write(''url'', l_url);',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>wwv_flow_imp.id(48465756592834580)
,p_internal_uid=>48487725805836642
);
end;
