wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(48488845763836692)
,p_process_sequence=>5
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P21_GET_AGENT_CATALOG'
,p_static_id=>'p21-get-agent-catalog'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_domain_id      number;',
'    l_domain_name    varchar2(256);',
'    l_base_url       varchar2(4000);',
'    l_token          varchar2(4000);',
'    l_response       clob;',
'    l_auth_response  clob;',
'    l_expires_at     varchar2(128);',
'    l_platform_token varchar2(4000);',
'    l_platform_expires_at varchar2(128);',
'    l_platform_seq   number;',
'    l_failed_apps    pls_integer := 0;',
'    l_context        kbot_apex_auth.t_context;',
'begin',
'    if not regexp_like(v(''P0_DOMAIN_ID''), ''^\d+$'') then',
unistr('        raise_application_error(-20001, ''\8BF7\5148\9009\62E9\6709\6548\7684\4E1A\52A1\57DF\3002'');'),
'    end if;',
'    l_domain_id := to_number(v(''P0_DOMAIN_ID''));',
'    select name',
'      into l_domain_name',
'      from kbot_platform_domain',
'     where domain_id = l_domain_id',
'       and status = ''ACTIVE'';',
'',
'    select max(',
'               case when protocol is not null and host is not null then',
'                   protocol || ''://'' || host ||',
'                   case when port is not null then '':'' || to_char(port) end',
'               end',
'           )',
'      into l_base_url',
'      from kbot_apex_platform_config',
'     where type_1 = ''KBOT_SERVICE''',
'       and type_2 = ''SERVICE''',
'       and status = ''ACTIVE'';',
'    if l_base_url is null then',
'        l_base_url := regexp_replace(',
'            rtrim(apex_util.host_url(''HOST''), ''/''),',
'            '':(8080|8181)$'',',
'            ''''',
'        );',
'    end if;',
'',
'    begin',
'        select seq_id, c007, c010',
'          into l_platform_seq, l_platform_token, l_platform_expires_at',
'          from apex_collections',
'         where collection_name = ''KBOT_ENTRY_TOKENS''',
'           and c001 = ''PLATFORM''',
'           and rownum = 1;',
'    exception',
'        when no_data_found then',
'            l_platform_seq := null;',
'            l_platform_token := null;',
'            l_platform_expires_at := null;',
'    end;',
'    if l_platform_token is not null',
'       and (l_platform_expires_at is null',
'            or substr(l_platform_expires_at, 1, 19) <=',
'               to_char(sys_extract_utc(systimestamp + interval ''5'' minute), ''YYYY-MM-DD"T"HH24:MI:SS'')) then',
'        apex_web_service.g_request_headers.delete;',
'        apex_web_service.g_request_headers(1).name := ''Authorization'';',
'        apex_web_service.g_request_headers(1).value := ''Bearer '' || l_platform_token;',
'        apex_web_service.g_request_headers(2).name := ''Accept'';',
'        apex_web_service.g_request_headers(2).value := ''application/json'';',
'        apex_web_service.g_request_headers(3).name := ''X-Request-ID'';',
'        apex_web_service.g_request_headers(3).value := lower(rawtohex(sys_guid()));',
'        l_auth_response := apex_web_service.make_rest_request(',
'            p_url => rtrim(l_base_url, ''/'') || ''/api/v1/auth/refresh'',',
'            p_http_method => ''POST''',
'        );',
'        if apex_web_service.g_status_code <> 200',
'           or upper(json_value(l_auth_response, ''$.entry_kind'')) <> ''PLATFORM'' then',
unistr('            raise_application_error(-20002, ''\5E73\53F0\767B\5F55\5DF2\8FC7\671F\FF0C\8BF7\91CD\65B0\767B\5F55\3002'');'),
'        end if;',
'        l_platform_token := json_value(l_auth_response, ''$.access_token'');',
'        l_platform_expires_at := json_value(l_auth_response, ''$.expires_at'');',
'        apex_collection.update_member_attribute(''KBOT_ENTRY_TOKENS'', l_platform_seq, 7, l_platform_token);',
'        apex_collection.update_member_attribute(''KBOT_ENTRY_TOKENS'', l_platform_seq, 10, l_platform_expires_at);',
'    end if;',
'',
'    apex_json.open_object;',
'    apex_json.open_array(''agents'');',
'    for app_rec in (',
'        select c001 app_id, max(c002) app_name, max(c004) domain_name',
'          from apex_collections',
'         where collection_name = ''KBOT_SSO_ENTRIES''',
'           and c001 = ''aiops''',
'           and c003 = to_char(l_domain_id)',
'           and (',
'               not exists (',
'                   select 1',
'                     from kbot_apex_platform_config feature_config',
'                    where feature_config.type_1 = ''PLATFORM_FEATURE''',
'               )',
'               or exists (',
'                   select 1',
'                     from kbot_apex_platform_config enabled_feature',
'                    where enabled_feature.type_1 = ''PLATFORM_FEATURE''',
'                      and enabled_feature.status = ''ACTIVE''',
'                      and enabled_feature.type_2 = ''AIOPS''',
'               )',
'           )',
'         group by c001',
'         order by app_id',
'    ) loop',
'        kbot_apex_auth.acquire_app_context(',
'            p_target_app => app_rec.app_id,',
'            p_requested_domain_id => l_domain_id,',
'            p_result => l_context,',
'            p_apply_context => false',
'        );',
'        if l_context.status <> ''READY'' then',
'            l_failed_apps := l_failed_apps + 1;',
'            continue;',
'        end if;',
'        begin',
'            select c007, c010',
'              into l_token, l_expires_at',
'              from (',
'                    select c007, c010',
'                      from apex_collections',
'                     where collection_name = ''KBOT_ENTRY_TOKENS''',
'                       and c001 = app_rec.app_id || '':'' || to_char(l_domain_id)',
'                       and c010 is not null',
'                       and substr(c010, 1, 19) >',
'                           to_char(sys_extract_utc(systimestamp + interval ''5'' minute), ''YYYY-MM-DD"T"HH24:MI:SS'')',
'                     order by seq_id desc',
'                   )',
'             where rownum = 1;',
'        exception',
'            when no_data_found then',
'            if l_platform_token is not null then',
'                apex_web_service.g_request_headers.delete;',
'                apex_web_service.g_request_headers(1).name := ''Authorization'';',
'                apex_web_service.g_request_headers(1).value := ''Bearer '' || l_platform_token;',
'                apex_web_service.g_request_headers(2).name := ''Content-Type'';',
'                apex_web_service.g_request_headers(2).value := ''application/json'';',
'                apex_web_service.g_request_headers(3).name := ''Accept'';',
'                apex_web_service.g_request_headers(3).value := ''application/json'';',
'                apex_web_service.g_request_headers(4).name := ''X-Request-ID'';',
'                apex_web_service.g_request_headers(4).value := lower(rawtohex(sys_guid()));',
'                l_auth_response := apex_web_service.make_rest_request(',
'                    p_url => rtrim(l_base_url, ''/'') || ''/api/v1/auth/exchange'',',
'                    p_http_method => ''POST'',',
'                    p_body => json_object(''app_id'' value app_rec.app_id, ''domain_id'' value l_domain_id)',
'                );',
'                if apex_web_service.g_status_code = 200 then',
'                    l_token := json_value(l_auth_response, ''$.access_token'');',
'                    l_expires_at := json_value(l_auth_response, ''$.expires_at'');',
'                    if l_token is not null',
'                       and l_expires_at is not null',
'                       and upper(json_value(l_auth_response, ''$.entry_kind'')) = ''BUSINESS''',
'                       and lower(json_value(l_auth_response, ''$.app_id'')) = app_rec.app_id',
'                       and json_value(l_auth_response, ''$.domain_id'' returning number) = l_domain_id then',
'                        apex_collection.delete_members(''KBOT_ENTRY_TOKENS'', 1, app_rec.app_id || '':'' || to_char(l_domain_id));',
'                        apex_collection.add_member(',
'                            p_collection_name => ''KBOT_ENTRY_TOKENS'',',
'                            p_c001 => app_rec.app_id || '':'' || to_char(l_domain_id),',
'                            p_c002 => ''BUSINESS'',',
'                            p_c003 => app_rec.app_id,',
'                            p_c004 => to_char(l_domain_id),',
'                            p_c005 => app_rec.app_name,',
'                            p_c006 => coalesce(json_value(l_auth_response, ''$.domain_name''), app_rec.domain_name),',
'                            p_c007 => l_token,',
'                            p_c008 => json_value(l_auth_response, ''$.display_name''),',
'                            p_c009 => case when lower(json_value(l_auth_response, ''$.must_change_password'')) = ''true'' then ''Y'' else ''N'' end,',
'                            p_c010 => l_expires_at',
'                        );',
'                    else',
'                        l_token := null;',
'                    end if;',
'                else',
'                    l_token := null;',
'                end if;',
'            else',
'                l_token := null;',
'            end if;',
'        end;',
'',
'        if l_token is not null then',
'            apex_web_service.g_request_headers.delete;',
'            apex_web_service.g_request_headers(1).name := ''Authorization'';',
'            apex_web_service.g_request_headers(1).value := ''Bearer '' || l_token;',
'            apex_web_service.g_request_headers(2).name := ''Accept'';',
'            apex_web_service.g_request_headers(2).value := ''application/json'';',
'            apex_web_service.g_request_headers(3).name := ''X-Request-ID'';',
'            apex_web_service.g_request_headers(3).value := lower(rawtohex(sys_guid()));',
'            l_response := apex_web_service.make_rest_request(',
'                p_url => rtrim(l_base_url, ''/'') || ''/api/v1/apps/aiops/agents'',',
'                p_http_method => ''GET''',
'            );',
'            if apex_web_service.g_status_code = 200 then',
'                for agent_rec in (',
'                    select agent_id, display_name, status, knowledge_core_id, target_ids',
'                      from json_table(',
'                               l_response,',
'                               ''$[*]'' columns (',
'                                   agent_id varchar2(64) path ''$.agent_id'',',
'                                   display_name varchar2(512) path ''$.display_name'',',
'                                   status varchar2(32) path ''$.status'',',
'                                   knowledge_core_id varchar2(64) path ''$.knowledge_core_id'',',
'                                   target_ids clob format json path ''$.target_ids''',
'                               )',
'                           )',
'                     where status = ''ACTIVE''',
'                ) loop',
'                    apex_json.open_object;',
'                    apex_json.write(''agent_id'', agent_rec.agent_id);',
'                    apex_json.write(''display_name'', agent_rec.display_name);',
'                    apex_json.write(''status'', agent_rec.status);',
'                    apex_json.write(''knowledge_core_id'', agent_rec.knowledge_core_id);',
'                    apex_json.write(''agent_kind'', ''aiops'');',
'                    apex_json.open_array(''target_ids'');',
'                    for target_rec in (',
'                        select target_id',
'                          from json_table(',
'                                   agent_rec.target_ids,',
'                                   ''$[*]'' columns (',
'                                       target_id varchar2(64) path ''$''',
'                                   )',
'                               )',
'                    ) loop',
'                        apex_json.write(target_rec.target_id);',
'                    end loop;',
'                    apex_json.close_array;',
'                    apex_json.close_object;',
'                end loop;',
'            else',
'                l_failed_apps := l_failed_apps + 1;',
'            end if;',
'        else',
'            l_failed_apps := l_failed_apps + 1;',
'        end if;',
'    end loop;',
'    apex_json.close_array;',
'    apex_json.write(''partial'', l_failed_apps > 0);',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
,p_internal_uid=>48488845763836692
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(48488933765836692)
,p_process_sequence=>6
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P21_GET_AGENT_CHAT_URL'
,p_static_id=>'p21-get-agent-chat-url'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_agent_id varchar2(64) := lower(trim(apex_application.g_x01));',
'    l_scope    varchar2(32) := lower(trim(apex_application.g_x02));',
'begin',
'    if not regexp_like(l_agent_id, ''^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'') then',
unistr('        raise_application_error(-20001, ''\667A\80FD\4F53 ID \65E0\6548\3002'');'),
'    end if;',
'    if l_scope <> ''aiops'' then',
unistr('        raise_application_error(-20002, ''\667A\80FD\4F53\6240\5C5E\5E94\7528\65E0\6548\3002'');'),
'    end if;',
'    apex_json.open_object;',
'    apex_json.write(',
'        ''url'',',
'        apex_page.get_url(',
'            p_page        => 21,',
'            p_clear_cache => ''21'',',
'            p_items       => ''P0_DOMAIN_ID,P21_AGENT_ID,P21_AGENT_SCOPE'',',
'            p_values      => :P0_DOMAIN_ID || '','' || l_agent_id || '','' || l_scope',
'        )',
'    );',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
,p_internal_uid=>48488933765836692
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(48489024429836692)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P21_GET_AGENT_URL'
,p_static_id=>'p21-get-agent-url'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    if not (kbot_apex_auth.is_platform_admin(:APP_USER) or kbot_apex_auth.has_permission(''aiops:agent_manage'')) then',
unistr('        raise_application_error(-20001, ''\5F53\524D\7528\6237\6CA1\6709\7BA1\7406 AIOps \667A\80FD\4F53\7684\6743\9650\3002'');'),
'    end if;',
'    apex_json.open_object;',
'    apex_json.write(''url'', apex_page.get_url(p_page => 56, p_clear_cache => ''56''));',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>'MUST_NOT_BE_PUBLIC_USER'
,p_internal_uid=>48489024429836692
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(48489259450836692)
,p_process_sequence=>24
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P21_GET_AIOPS_CONVERSATION_REPORTS'
,p_static_id=>'p21-get-aiops-conversation-reports'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_conversation_id varchar2(36) := lower(trim(apex_application.g_x01));',
'begin',
'    if not regexp_like(',
'        l_conversation_id,',
'        ''^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$''',
'    ) then',
unistr('        raise_application_error(-20001, ''Conversation ID \65E0\6548'');'),
'    end if;',
'',
'    apex_json.open_object;',
'    apex_json.open_array(''items'');',
'    for r in (',
'        select lower(substr(rawtohex(rp.report_id), 1, 8) || ''-'' ||',
'                     substr(rawtohex(rp.report_id), 9, 4) || ''-'' ||',
'                     substr(rawtohex(rp.report_id), 13, 4) || ''-'' ||',
'                     substr(rawtohex(rp.report_id), 17, 4) || ''-'' ||',
'                     substr(rawtohex(rp.report_id), 21, 12)) as report_id,',
'               lower(substr(rawtohex(rp.ops_run_id), 1, 8) || ''-'' ||',
'                     substr(rawtohex(rp.ops_run_id), 9, 4) || ''-'' ||',
'                     substr(rawtohex(rp.ops_run_id), 13, 4) || ''-'' ||',
'                     substr(rawtohex(rp.ops_run_id), 17, 4) || ''-'' ||',
'                     substr(rawtohex(rp.ops_run_id), 21, 12)) as ops_run_id,',
'               rp.title,',
'               rp.report_version,',
'               rp.created_at',
'          from kbot_ops_report rp',
'          join kbot_ops_run ru on ru.ops_run_id = rp.ops_run_id',
'          join kbot_ops_artifact a on a.artifact_id = rp.content_artifact_id',
'         where ru.domain_id = :P0_DOMAIN_ID',
'           and rp.is_current = 1',
'           and rp.status in (''READY'', ''PARTIAL'')',
'           and lower(json_value(',
'               a.payload_json,',
'               ''$.scope.conversation.conversation_id''',
'               returning varchar2(36) null on error',
'           )) = l_conversation_id',
'         order by rp.created_at desc, rp.report_id desc',
'         fetch first 20 rows only',
'    ) loop',
'        apex_json.open_object;',
'        apex_json.write(''report_id'', r.report_id);',
'        apex_json.write(''ops_run_id'', r.ops_run_id);',
'        apex_json.write(''title'', r.title);',
'        apex_json.write(''report_version'', r.report_version);',
'        apex_json.write(',
'            ''created_at'',',
'            to_char(r.created_at, ''YYYY-MM-DD"T"HH24:MI:SSTZH:TZM'')',
'        );',
'        apex_json.close_object;',
'    end loop;',
'    apex_json.close_array;',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>wwv_flow_imp.id(48468648780834581)
,p_internal_uid=>48489259450836692
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(48489313746836692)
,p_process_sequence=>25
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P21_GET_AIOPS_RESOURCE_URL'
,p_static_id=>'p21-get-aiops-resource-url'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_kind varchar2(30) := lower(trim(apex_application.g_x01));',
'    l_id   varchar2(64) := trim(apex_application.g_x02);',
'    l_page number;',
'    l_item varchar2(30);',
'begin',
'    if l_kind = ''hitl'' then',
'        l_page := 53;',
'        l_item := ''P53_HITL_ID'';',
'    elsif l_kind = ''proposal'' then',
'        l_page := 54;',
'        l_item := ''P54_PROPOSAL_ID'';',
'    elsif l_kind = ''report'' then',
'        l_page := 57;',
'        l_item := ''P57_VIEW,P57_REPORT_ID'';',
'        l_id := ''REPORTS,'' || l_id;',
'    elsif l_kind = ''ops_run'' then',
'        l_page := 52;',
'        l_item := ''P52_RUN_ID'';',
'    elsif l_kind = ''report_generate'' then',
'        l_page := 110;',
'        l_item := ''P110_CONVERSATION_ID'';',
'    else',
