,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P57_LOAD_REPORT_DETAIL'
,p_static_id=>'p57-load-report-detail'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_report_id  raw(16);',
'    l_ops_run_id raw(16);',
'    l_report_key varchar2(128);',
'    l_found      boolean := false;',
'begin',
'    if not regexp_like(trim(apex_application.g_x01), ''^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'') then',
unistr('        raise_application_error(-20001, ''Report ID \65E0\6548'');'),
'    end if;',
'    l_report_id := hextoraw(replace(trim(apex_application.g_x01), ''-'', ''''));',
'',
'    apex_json.open_object;',
'    for r in (',
'        select rp.ops_run_id,',
'               rp.report_key,',
'               lower(substr(rawtohex(rp.report_id), 1, 8) || ''-'' ||',
'                     substr(rawtohex(rp.report_id), 9, 4) || ''-'' ||',
'                     substr(rawtohex(rp.report_id), 13, 4) || ''-'' ||',
'                     substr(rawtohex(rp.report_id), 17, 4) || ''-'' ||',
'                     substr(rawtohex(rp.report_id), 21, 12)) as report_id,',
'               lower(substr(rawtohex(rp.target_id), 1, 8) || ''-'' ||',
'                     substr(rawtohex(rp.target_id), 9, 4) || ''-'' ||',
'                     substr(rawtohex(rp.target_id), 13, 4) || ''-'' ||',
'                     substr(rawtohex(rp.target_id), 17, 4) || ''-'' ||',
'                     substr(rawtohex(rp.target_id), 21, 12)) as target_id,',
'               rp.report_version,',
'               rp.report_type,',
'               rp.title,',
'               rp.summary,',
'               rp.status,',
'               rp.period_start,',
'               rp.period_end,',
'               rp.created_at,',
'               case when rp.supersedes_report_id is not null then',
'                   lower(substr(rawtohex(rp.supersedes_report_id), 1, 8) || ''-'' ||',
'                         substr(rawtohex(rp.supersedes_report_id), 9, 4) || ''-'' ||',
'                         substr(rawtohex(rp.supersedes_report_id), 13, 4) || ''-'' ||',
'                         substr(rawtohex(rp.supersedes_report_id), 17, 4) || ''-'' ||',
'                         substr(rawtohex(rp.supersedes_report_id), 21, 12))',
'               end as corrected_from_report_id,',
'               json_serialize(a.payload_json returning clob) as payload_json',
'          from kbot_ops_report rp',
'          join kbot_ops_run ru on ru.ops_run_id = rp.ops_run_id',
'          left join kbot_ops_artifact a on a.artifact_id = rp.content_artifact_id',
'         where rp.report_id = l_report_id',
'           and ru.domain_id = :P0_DOMAIN_ID',
'    ) loop',
'        l_found := true;',
'        l_ops_run_id := r.ops_run_id;',
'        l_report_key := r.report_key;',
'        apex_json.open_object(''report'');',
'        apex_json.write(''report_id'', r.report_id);',
'        apex_json.write(''report_key'', r.report_key);',
'        apex_json.write(''report_version'', r.report_version);',
'        apex_json.write(''report_type'', r.report_type);',
'        apex_json.write(''title'', r.title);',
'        apex_json.write(''summary'', r.summary);',
'        apex_json.write(''status'', r.status);',
'        apex_json.write(''target_id'', r.target_id);',
'        apex_json.write(',
'            ''ops_run_id'',',
'            lower(substr(rawtohex(l_ops_run_id), 1, 8) || ''-'' ||',
'                  substr(rawtohex(l_ops_run_id), 9, 4) || ''-'' ||',
'                  substr(rawtohex(l_ops_run_id), 13, 4) || ''-'' ||',
'                  substr(rawtohex(l_ops_run_id), 17, 4) || ''-'' ||',
'                  substr(rawtohex(l_ops_run_id), 21, 12))',
'        );',
'        apex_json.write(''period_start'', to_char(r.period_start, ''YYYY-MM-DD"T"HH24:MI:SSTZH:TZM''));',
'        apex_json.write(''period_end'', to_char(r.period_end, ''YYYY-MM-DD"T"HH24:MI:SSTZH:TZM''));',
'        apex_json.write(''published_at'', to_char(r.created_at, ''YYYY-MM-DD"T"HH24:MI:SSTZH:TZM''));',
'        apex_json.write(''corrected_from_report_id'', r.corrected_from_report_id);',
'        apex_json.write(''payload_json'', r.payload_json);',
'        apex_json.close_object;',
'    end loop;',
'',
'    if not l_found then',
'        apex_json.write(''success'', false);',
unistr('        apex_json.write(''error'', ''\5F53\524D\4E1A\52A1\57DF\4E2D\672A\627E\5230\8BE5\62A5\544A\3002'');'),
'    else',
'        apex_json.open_array(''versions'');',
'        for r in (',
'            select lower(substr(rawtohex(rp.report_id), 1, 8) || ''-'' ||',
'                         substr(rawtohex(rp.report_id), 9, 4) || ''-'' ||',
'                         substr(rawtohex(rp.report_id), 13, 4) || ''-'' ||',
'                         substr(rawtohex(rp.report_id), 17, 4) || ''-'' ||',
'                         substr(rawtohex(rp.report_id), 21, 12)) as report_id,',
'                   rp.report_version,',
'                   rp.status,',
'                   rp.created_at',
'              from kbot_ops_report rp',
'             where rp.ops_run_id = l_ops_run_id',
'               and rp.report_key = l_report_key',
'             order by rp.report_version desc, rp.created_at desc',
'             fetch first 200 rows only',
'        ) loop',
'            apex_json.open_object;',
'            apex_json.write(''report_id'', r.report_id);',
'            apex_json.write(''report_version'', r.report_version);',
'            apex_json.write(''status'', r.status);',
'            apex_json.write(''published_at'', to_char(r.created_at, ''YYYY-MM-DD"T"HH24:MI:SSTZH:TZM''));',
'            apex_json.close_object;',
'        end loop;',
'        apex_json.close_array;',
'    end if;',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>wwv_flow_imp.id(48468648780834581)
,p_internal_uid=>48495706824836746
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(48495625546836746)
,p_process_sequence=>30
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P57_LOAD_REPORTS'
,p_static_id=>'p57-load-reports'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_report_type varchar2(32) := upper(trim(apex_application.g_x01));',
'    l_target_id   raw(16);',
'begin',
'    if l_report_type is not null and not regexp_like(l_report_type, ''^[A-Z0-9_]{1,32}$'') then',
unistr('        raise_application_error(-20001, ''\62A5\544A\7C7B\578B\7B5B\9009\6761\4EF6\65E0\6548'');'),
'    end if;',
'',
'    if trim(apex_application.g_x02) is not null then',
'        if not regexp_like(trim(apex_application.g_x02), ''^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'') then',
unistr('            raise_application_error(-20002, ''\8FD0\7EF4\76EE\6807\5E93 ID \65E0\6548'');'),
'        end if;',
'        l_target_id := hextoraw(replace(trim(apex_application.g_x02), ''-'', ''''));',
'    end if;',
'',
'    apex_json.open_object;',
'    apex_json.open_array(''items'');',
'    for r in (',
'        select lower(substr(rawtohex(rp.report_id), 1, 8) || ''-'' ||',
'                     substr(rawtohex(rp.report_id), 9, 4) || ''-'' ||',
'                     substr(rawtohex(rp.report_id), 13, 4) || ''-'' ||',
'                     substr(rawtohex(rp.report_id), 17, 4) || ''-'' ||',
'                     substr(rawtohex(rp.report_id), 21, 12)) as report_id,',
'               rp.report_key,',
'               rp.report_version,',
'               rp.report_type,',
'               rp.title,',
'               rp.summary,',
'               rp.status,',
'               lower(substr(rawtohex(rp.target_id), 1, 8) || ''-'' ||',
'                     substr(rawtohex(rp.target_id), 9, 4) || ''-'' ||',
'                     substr(rawtohex(rp.target_id), 13, 4) || ''-'' ||',
'                     substr(rawtohex(rp.target_id), 17, 4) || ''-'' ||',
'                     substr(rawtohex(rp.target_id), 21, 12)) as target_id,',
'               rp.period_start,',
'               rp.period_end,',
'               rp.created_at',
'          from kbot_ops_report rp',
'          join kbot_ops_run ru on ru.ops_run_id = rp.ops_run_id',
'         where ru.domain_id = :P0_DOMAIN_ID',
'           and rp.is_current = 1',
'           and (l_report_type is null or rp.report_type = l_report_type)',
'           and (l_target_id is null or rp.target_id = l_target_id)',
'         order by rp.created_at desc, rp.report_id desc',
'         fetch first 200 rows only',
'    ) loop',
'        apex_json.open_object;',
'        apex_json.write(''report_id'', r.report_id);',
'        apex_json.write(''report_key'', r.report_key);',
'        apex_json.write(''report_version'', r.report_version);',
'        apex_json.write(''report_type'', r.report_type);',
'        apex_json.write(''title'', r.title);',
'        apex_json.write(''summary'', r.summary);',
'        apex_json.write(''status'', r.status);',
'        apex_json.write(''target_id'', r.target_id);',
'        apex_json.write(''period_start'', to_char(r.period_start, ''YYYY-MM-DD"T"HH24:MI:SSTZH:TZM''));',
'        apex_json.write(''period_end'', to_char(r.period_end, ''YYYY-MM-DD"T"HH24:MI:SSTZH:TZM''));',
'        apex_json.write(''published_at'', to_char(r.created_at, ''YYYY-MM-DD"T"HH24:MI:SSTZH:TZM''));',
'        apex_json.close_object;',
'    end loop;',
'    apex_json.close_array;',
'    apex_json.write(''has_more'', false);',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>wwv_flow_imp.id(48468648780834581)
,p_internal_uid=>48495625546836746
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(48495428052836746)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P57_LOAD_RESOURCES'
,p_static_id=>'p57-load-resources'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    apex_json.open_object;',
'',
'    apex_json.open_array(''targets'');',
'    for r in (',
'        select lower(',
'                   substr(rawtohex(target_id), 1, 8) || ''-'' ||',
'                   substr(rawtohex(target_id), 9, 4) || ''-'' ||',
'                   substr(rawtohex(target_id), 13, 4) || ''-'' ||',
'                   substr(rawtohex(target_id), 17, 4) || ''-'' ||',
'                   substr(rawtohex(target_id), 21, 12)',
'               ) as target_id,',
'               display_name',
'          from kbot_ops_target',
'         where domain_id = :P0_DOMAIN_ID',
'         order by upper(display_name), target_id',
'    ) loop',
'        apex_json.open_object;',
'        apex_json.write(''target_id'', r.target_id);',
'        apex_json.write(''display_name'', r.display_name);',
'        apex_json.close_object;',
'    end loop;',
'    apex_json.close_array;',
'',
'    apex_json.open_array(''agents'');',
'    for r in (',
'        select lower(',
'                   substr(rawtohex(agent_id), 1, 8) || ''-'' ||',
'                   substr(rawtohex(agent_id), 9, 4) || ''-'' ||',
'                   substr(rawtohex(agent_id), 13, 4) || ''-'' ||',
'                   substr(rawtohex(agent_id), 17, 4) || ''-'' ||',
'                   substr(rawtohex(agent_id), 21, 12)',
'               ) as agent_id,',
'               display_name',
'          from kbot_ops_agent',
'         where domain_id = :P0_DOMAIN_ID',
'         order by upper(display_name), agent_id',
'    ) loop',
'        apex_json.open_object;',
'        apex_json.write(''agent_id'', r.agent_id);',
'        apex_json.write(''display_name'', r.display_name);',
'        apex_json.close_object;',
'    end loop;',
'    apex_json.close_array;',
'',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>wwv_flow_imp.id(48468648780834581)
,p_internal_uid=>48495428052836746
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(48495574405836746)
,p_process_sequence=>20
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P57_LOAD_RUNS'
,p_static_id=>'p57-load-runs'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_status    varchar2(24) := upper(trim(apex_application.g_x01));',
'    l_target_id raw(16);',
'    l_offset     pls_integer := 0;',
'    l_count      pls_integer := 0;',
'    l_sort_order varchar2(4) := nvl(upper(trim(apex_application.g_x04)), ''DESC'');',
'begin',
'    if l_status is not null and l_status not in (',
'        ''CREATED'', ''QUEUED'', ''RUNNING'', ''WAITING_INPUT'',',
'        ''WAITING_APPROVAL'', ''COMPLETED'', ''PARTIAL'', ''FAILED'',',
'        ''CANCELLED'', ''EXPIRED''',
'    ) then',
unistr('        raise_application_error(-20001, ''\8FD0\884C\72B6\6001\7B5B\9009\503C\65E0\6548\3002'');'),
'    end if;',
'',
'    if trim(apex_application.g_x02) is not null then',
'        if not regexp_like(',
'            trim(apex_application.g_x02),',
'            ''^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$''',
'        ) then',
unistr('            raise_application_error(-20002, ''\8FD0\7EF4\76EE\6807\5E93 ID \683C\5F0F\65E0\6548\3002'');'),
'        end if;',
'        l_target_id := hextoraw(replace(trim(apex_application.g_x02), ''-'', ''''));',
'    end if;',
'',
'    if trim(apex_application.g_x03) is not null then',
'        begin',
'            l_offset := to_number(trim(apex_application.g_x03));',
'        exception',
'            when value_error then',
unistr('                raise_application_error(-20003, ''\5206\9875\6E38\6807\65E0\6548\3002'');'),
'        end;',
'    end if;',
'    if l_offset < 0 or l_offset > 1000000 then',
unistr('        raise_application_error(-20003, ''\5206\9875\6E38\6807\65E0\6548\3002'');'),
'    end if;',
'',
'    if l_sort_order not in (''ASC'', ''DESC'') then',
unistr('        raise_application_error(-20004, ''\65F6\95F4\6392\5E8F\503C\65E0\6548\3002'');'),
'    end if;',
'',
'    apex_json.open_object;',
'    apex_json.open_array(''items'');',
'    for r in (',
'        select lower(',
'                   substr(rawtohex(ops_run_id), 1, 8) || ''-'' ||',
'                   substr(rawtohex(ops_run_id), 9, 4) || ''-'' ||',
'                   substr(rawtohex(ops_run_id), 13, 4) || ''-'' ||',
'                   substr(rawtohex(ops_run_id), 17, 4) || ''-'' ||',
'                   substr(rawtohex(ops_run_id), 21, 12)',
'               ) as ops_run_id,',
'               lower(',
'                   substr(rawtohex(target_id), 1, 8) || ''-'' ||',
'                   substr(rawtohex(target_id), 9, 4) || ''-'' ||',
'                   substr(rawtohex(target_id), 13, 4) || ''-'' ||',
'                   substr(rawtohex(target_id), 17, 4) || ''-'' ||',
'                   substr(rawtohex(target_id), 21, 12)',
'               ) as target_id,',
'               lower(',
'                   substr(rawtohex(agent_id), 1, 8) || ''-'' ||',
'                   substr(rawtohex(agent_id), 9, 4) || ''-'' ||',
'                   substr(rawtohex(agent_id), 13, 4) || ''-'' ||',
'                   substr(rawtohex(agent_id), 17, 4) || ''-'' ||',
'                   substr(rawtohex(agent_id), 21, 12)',
'               ) as agent_id,',
'               trigger_type, workflow_kind, interaction_mode, status,',
'               row_version, created_at, completed_at',
'          from kbot_ops_run',
'         where domain_id = :P0_DOMAIN_ID',
'           and (l_status is null or status = l_status)',
'           and (l_target_id is null or target_id = l_target_id)',
'         order by',
'               case when l_sort_order = ''ASC'' then created_at end asc,',
'               case when l_sort_order = ''ASC'' then ops_run_id end asc,',
'               case when l_sort_order = ''DESC'' then created_at end desc,',
'               case when l_sort_order = ''DESC'' then ops_run_id end desc',
'         offset l_offset rows fetch next 51 rows only',
'    ) loop',
'        l_count := l_count + 1;',
'        exit when l_count > 50;',
'        apex_json.open_object;',
'        apex_json.write(''ops_run_id'', r.ops_run_id);',
'        apex_json.write(''target_id'', r.target_id);',
'        apex_json.write(''agent_id'', r.agent_id);',
'        apex_json.write(''trigger_type'', r.trigger_type);',
'        apex_json.write(''workflow_kind'', r.workflow_kind);',
'        apex_json.write(''interaction_mode'', r.interaction_mode);',
'        apex_json.write(''status'', r.status);',
'        apex_json.write(''row_version'', r.row_version);',
'        apex_json.write(''created_at'', to_char(r.created_at, ''YYYY-MM-DD"T"HH24:MI:SSTZH:TZM''));',
'        apex_json.write(',
'            ''completed_at'',',
'            case when r.completed_at is not null',
'                 then to_char(r.completed_at, ''YYYY-MM-DD"T"HH24:MI:SSTZH:TZM'')',
'            end',
'        );',
'        apex_json.close_object;',
'    end loop;',
'    apex_json.close_array;',
'    apex_json.write(''has_more'', l_count > 50);',
'    apex_json.write(',
'        ''next_cursor'',',
'        case when l_count > 50 then to_char(l_offset + 50) end',
'    );',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>wwv_flow_imp.id(48468648780834581)
,p_internal_uid=>48495574405836746
);
end;
