,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select lower(substr(rawtohex(s.situation_id), 1, 8) || ''-'' ||',
'             substr(rawtohex(s.situation_id), 9, 4) || ''-'' ||',
'             substr(rawtohex(s.situation_id), 13, 4) || ''-'' ||',
'             substr(rawtohex(s.situation_id), 17, 4) || ''-'' ||',
'             substr(rawtohex(s.situation_id), 21, 12)) as situation_id,',
'       s.title,',
'       s.summary,',
'       case upper(s.severity)',
unistr('           when ''INFO'' then ''\4FE1\606F'''),
unistr('           when ''WARNING'' then ''\8B66\544A'''),
unistr('           when ''HIGH'' then ''\9AD8'''),
unistr('           when ''CRITICAL'' then ''\4E25\91CD'''),
unistr('           else nvl(s.severity, ''\672A\77E5'')'),
'       end as severity,',
'       case upper(s.status)',
unistr('           when ''OPEN'' then ''\5904\7406\4E2D'''),
unistr('           when ''ACKNOWLEDGED'' then ''\5DF2\786E\8BA4'''),
unistr('           when ''RESOLVED'' then ''\5DF2\89E3\51B3'''),
unistr('           when ''CLOSED'' then ''\5DF2\5173\95ED'''),
unistr('           else nvl(s.status, ''\672A\77E5'')'),
'       end as status,',
unistr('       coalesce(t.display_name, ''\672A\547D\540D\8FD0\7EF4\76EE\6807\5E93'') as target_name,'),
unistr('       nvl(ra.agent_names, ''\672A\8BCA\65AD'') as agent_names,'),
'       t.importance_level,',
'       s.event_count,',
'       s.last_observed_at',
'  from kbot_ops_situation s',
'  left join kbot_ops_target t',
'    on t.target_id = s.target_id',
'   and t.domain_id = s.domain_id',
'  left join (',
'      select r.domain_id,',
'             r.situation_id,',
unistr('             listagg(distinct a.display_name, ''\3001'')'),
'                 within group (order by a.display_name) as agent_names',
'        from kbot_ops_run r',
'        join kbot_ops_agent a',
'          on a.agent_id = r.agent_id',
'         and a.domain_id = r.domain_id',
'       where r.situation_id is not null',
'       group by r.domain_id, r.situation_id',
'  ) ra',
'    on ra.situation_id = s.situation_id',
'   and ra.domain_id = s.domain_id',
' where s.domain_id = :P0_DOMAIN_ID',
'   and (:P58_SITUATION_FILTER is null',
'        or s.title || chr(31) || nvl(t.display_name, ''~'') = :P58_SITUATION_FILTER)',
'   and (:P58_TARGET_FILTER is null',
'        or lower(rawtohex(t.target_id)) = :P58_TARGET_FILTER)',
'   and (:P58_AGENT_FILTER is null',
'        or exists (',
'            select 1',
'              from kbot_ops_run fr',
'             where fr.situation_id = s.situation_id',
'               and fr.domain_id = s.domain_id',
'               and lower(rawtohex(fr.agent_id)) = :P58_AGENT_FILTER',
'        ))',
'   and (:P58_IMPORTANCE_FILTER is null',
'        or t.importance_level = to_number(:P58_IMPORTANCE_FILTER))',
'   and (:P58_SEVERITY_FILTER is null',
'        or s.severity = :P58_SEVERITY_FILTER)',
'   and (:P58_STATUS_FILTER is null',
'        or s.status = :P58_STATUS_FILTER)',
' order by s.last_observed_at desc,',
'          s.situation_id desc'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P0_DOMAIN_ID,P58_SITUATION_FILTER,P58_TARGET_FILTER,P58_AGENT_FILTER,P58_IMPORTANCE_FILTER,P58_SEVERITY_FILTER,P58_STATUS_FILTER'
