wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(48498540954836800)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P58_LOAD_RUNTIME'
,p_static_id=>'p58-load-runtime'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_domain_id number;',
'    l_kind varchar2(32) := upper(trim(apex_application.g_x01));',
'    l_resource_id raw(16);',
'',
'    function uuid_text(p_value raw) return varchar2 is',
'        l_hex varchar2(32);',
'    begin',
'        if p_value is null then',
'            return null;',
'        end if;',
'        l_hex := lower(rawtohex(p_value));',
'        return substr(l_hex, 1, 8) || ''-'' || substr(l_hex, 9, 4) || ''-'' ||',
'               substr(l_hex, 13, 4) || ''-'' || substr(l_hex, 17, 4) || ''-'' ||',
'               substr(l_hex, 21, 12);',
'    end;',
'',
'    function utc_text(p_value timestamp with time zone) return varchar2 is',
'    begin',
'        if p_value is null then',
'            return null;',
'        end if;',
'        return to_char(p_value at time zone ''UTC'', ''YYYY-MM-DD"T"HH24:MI:SS.FF3"Z"'');',
'    end;',
'begin',
'    l_domain_id := to_number(v(''P0_DOMAIN_ID''));',
'    if l_domain_id is null then',
unistr('        raise_application_error(-20001, ''\8BF7\5148\9009\62E9\5F53\524D\4E1A\52A1\57DF\3002'');'),
'    end if;',
'',
'    if l_kind not in (''SITUATIONS'', ''SITUATION_DETAIL'') then',
unistr('        raise_application_error(-20003, ''\5F53\524D\9875\9762\4E0D\652F\6301\8BE5\8BFB\53D6\7C7B\578B\3002'');'),
'    end if;',
'',
'    if l_kind in (''FIRE_DETAIL'', ''SITUATION_DETAIL'') then',
'        if not regexp_like(trim(apex_application.g_x02),',
'            ''^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}$'') then',
unistr('            raise_application_error(-20002, ''\8D44\6E90\6807\8BC6\65E0\6548\3002'');'),
'        end if;',
'        l_resource_id := hextoraw(replace(trim(apex_application.g_x02), ''-'', ''''));',
'    end if;',
'',
'    apex_json.open_object;',
'    apex_json.write(''success'', true);',
'',
'    if l_kind = ''FIRES'' then',
'        apex_json.open_array(''items'');',
'        for r in (',
'            select f.inspection_fire_id,',
'                   f.inspection_plan_id,',
'                   p.display_name plan_name,',
'                   f.scheduled_for,',
'                   f.status,',
'                   f.target_count,',
'                   f.run_count,',
'                   f.completed_count,',
'                   f.failed_count',
'              from kbot_ops_inspection_fire f',
'              join kbot_ops_inspection_plan p',
'                on p.inspection_plan_id = f.inspection_plan_id',
'             where p.domain_id = l_domain_id',
'             order by f.created_at desc, f.inspection_fire_id desc',
'             fetch first 200 rows only',
'        ) loop',
'            apex_json.open_object;',
'            apex_json.write(''fire_id'', uuid_text(r.inspection_fire_id));',
'            apex_json.write(''plan_id'', uuid_text(r.inspection_plan_id));',
'            apex_json.write(''plan_name'', r.plan_name);',
'            apex_json.write(''scheduled_at'', utc_text(r.scheduled_for));',
'            apex_json.write(''status'', r.status);',
'            apex_json.write(''target_count'', r.target_count);',
'            apex_json.write(''run_count'', r.run_count);',
'            apex_json.write(''completed_count'', r.completed_count);',
'            apex_json.write(''failed_count'', r.failed_count);',
'            apex_json.close_object;',
'        end loop;',
'        apex_json.close_array;',
'',
'    elsif l_kind = ''FIRE_DETAIL'' then',
'        for r in (',
'            select f.inspection_fire_id,',
'                   f.inspection_plan_id,',
'                   p.display_name plan_name,',
'                   f.scheduled_for,',
'                   f.status,',
'                   f.target_count,',
'                   f.run_count,',
'                   f.completed_count,',
'                   f.failed_count,',
'                   f.created_at,',
'                   f.completed_at',
'              from kbot_ops_inspection_fire f',
'              join kbot_ops_inspection_plan p',
'                on p.inspection_plan_id = f.inspection_plan_id',
'             where f.inspection_fire_id = l_resource_id',
'               and p.domain_id = l_domain_id',
'        ) loop',
'            apex_json.open_object(''item'');',
'            apex_json.write(''fire_id'', uuid_text(r.inspection_fire_id));',
'            apex_json.write(''plan_id'', uuid_text(r.inspection_plan_id));',
'            apex_json.write(''plan_name'', r.plan_name);',
'            apex_json.write(''scheduled_at'', utc_text(r.scheduled_for));',
'            apex_json.write(''status'', r.status);',
'            apex_json.write(''target_count'', r.target_count);',
'            apex_json.write(''run_count'', r.run_count);',
'            apex_json.write(''completed_count'', r.completed_count);',
'            apex_json.write(''failed_count'', r.failed_count);',
'            apex_json.write(''created_at'', utc_text(r.created_at));',
'            apex_json.write(''completed_at'', utc_text(r.completed_at));',
'            apex_json.open_array(''run_ids'');',
'            for rr in (',
'                select ops_run_id',
'                  from kbot_ops_run',
'                 where inspection_fire_id = r.inspection_fire_id',
'                   and domain_id = l_domain_id',
'                 order by created_at desc',
'            ) loop',
'                apex_json.write(uuid_text(rr.ops_run_id));',
'            end loop;',
'            apex_json.close_array;',
'            apex_json.close_object;',
'        end loop;',
'',
'    elsif l_kind = ''SITUATIONS'' then',
'        apex_json.open_array(''items'');',
'        for r in (',
'            select s.situation_id,',
'                   s.target_id,',
'                   t.display_name target_name,',
'                   t.importance_level,',
'                   s.situation_type,',
'                   s.title,',
'                   s.summary,',
'                   s.status,',
'                   s.severity,',
'                   s.event_count,',
'                   s.row_version,',
'                   s.first_observed_at,',
'                   s.last_observed_at,',
'                   s.resolved_at',
'              from kbot_ops_situation s',
'              left join kbot_ops_target t',
'                on t.target_id = s.target_id',
'               and t.domain_id = s.domain_id',
'             where s.domain_id = l_domain_id',
'             order by s.last_observed_at desc, s.situation_id desc',
'             fetch first 200 rows only',
'        ) loop',
'            apex_json.open_object;',
'            apex_json.write(''situation_id'', uuid_text(r.situation_id));',
'            apex_json.write(''target_id'', uuid_text(r.target_id));',
'            apex_json.write(''target_name'', r.target_name);',
'            apex_json.write(''importance_level'', r.importance_level);',
'            apex_json.write(''situation_type'', r.situation_type);',
'            apex_json.write(''title'', r.title);',
'            apex_json.write(''summary'', r.summary);',
'            apex_json.write(''status'', r.status);',
'            apex_json.write(''severity'', r.severity);',
'            apex_json.write(''event_count'', r.event_count);',
'            apex_json.write(''row_version'', r.row_version);',
'            apex_json.write(''first_observed_at'', utc_text(r.first_observed_at));',
'            apex_json.write(''last_observed_at'', utc_text(r.last_observed_at));',
'            apex_json.write(''resolved_at'', utc_text(r.resolved_at));',
'            apex_json.close_object;',
'        end loop;',
'        apex_json.close_array;',
'',
'    elsif l_kind = ''SITUATION_DETAIL'' then',
'        for r in (',
'            select s.situation_id,',
'                   s.target_id,',
'                   t.display_name target_name,',
'                   t.importance_level,',
'                   s.situation_type,',
'                   s.title,',
'                   s.summary,',
'                   s.status,',
'                   s.severity,',
'                   s.event_count,',
'                   s.row_version,',
'                   s.first_observed_at,',
'                   s.last_observed_at,',
'                   s.resolved_at',
'              from kbot_ops_situation s',
'              left join kbot_ops_target t',
'                on t.target_id = s.target_id',
'               and t.domain_id = s.domain_id',
'             where s.situation_id = l_resource_id',
'               and s.domain_id = l_domain_id',
'        ) loop',
'            apex_json.open_object(''item'');',
'            apex_json.write(''situation_id'', uuid_text(r.situation_id));',
'            apex_json.write(''target_id'', uuid_text(r.target_id));',
'            apex_json.write(''target_name'', r.target_name);',
'            apex_json.write(''importance_level'', r.importance_level);',
'            apex_json.write(''situation_type'', r.situation_type);',
'            apex_json.write(''title'', r.title);',
'            apex_json.write(''summary'', r.summary);',
'            apex_json.write(''status'', r.status);',
'            apex_json.write(''severity'', r.severity);',
'            apex_json.write(''event_count'', r.event_count);',
'            apex_json.write(''row_version'', r.row_version);',
'            apex_json.write(''first_observed_at'', utc_text(r.first_observed_at));',
'            apex_json.write(''last_observed_at'', utc_text(r.last_observed_at));',
'            apex_json.write(''resolved_at'', utc_text(r.resolved_at));',
'',
'            apex_json.open_array(''monitoring_sources'');',
'            for sr in (',
'                select e.diagnostic_source_id,',
'                       max(d.display_name) display_name,',
'                       max(d.source_type) source_type,',
'                       count(*) event_count,',
'                       min(e.occurred_at) first_observed_at,',
'                       max(e.occurred_at) last_observed_at,',
'                       max(e.event_class) keep (dense_rank last order by e.occurred_at) latest_event_class,',
'                       max(e.severity) keep (dense_rank last order by e.occurred_at) latest_severity,',
'                       max(e.normalized_status) keep (dense_rank last order by e.occurred_at) latest_status,',
'                       max(e.summary) keep (dense_rank last order by e.occurred_at) latest_summary',
'                  from kbot_ops_situation_event se',
'                  join kbot_ops_signal_event e',
'                    on e.signal_event_id = se.signal_event_id',
'                  left join kbot_ops_diagnostic_source d',
'                    on d.diagnostic_source_id = e.diagnostic_source_id',
'                   and d.domain_id = e.domain_id',
'                 where se.situation_id = r.situation_id',
'                   and e.domain_id = l_domain_id',
'                 group by e.diagnostic_source_id',
'                 order by max(e.occurred_at) desc',
'            ) loop',
'                apex_json.open_object;',
'                apex_json.write(''diagnostic_source_id'', uuid_text(sr.diagnostic_source_id));',
'                apex_json.write(''display_name'', sr.display_name);',
'                apex_json.write(''source_type'', sr.source_type);',
'                apex_json.write(''event_count'', sr.event_count);',
'                apex_json.write(''first_observed_at'', utc_text(sr.first_observed_at));',
'                apex_json.write(''last_observed_at'', utc_text(sr.last_observed_at));',
'                apex_json.write(''latest_event_class'', sr.latest_event_class);',
'                apex_json.write(''latest_severity'', sr.latest_severity);',
'                apex_json.write(''latest_status'', sr.latest_status);',
'                apex_json.write(''latest_summary'', sr.latest_summary);',
'                apex_json.close_object;',
'            end loop;',
'            apex_json.close_array;',
'',
'            apex_json.open_array(''signal_events'');',
'            for er in (',
'                select * from (',
'                    select e.signal_event_id,',
'                           e.diagnostic_source_id,',
'                           e.source_event_key,',
'                           e.signal_kind,',
'                           e.event_class,',
'                           e.severity,',
'                           e.normalized_status,',
'                           e.summary,',
'                           e.occurred_at',
'                      from kbot_ops_situation_event se',
'                      join kbot_ops_signal_event e',
'                        on e.signal_event_id = se.signal_event_id',
'                     where se.situation_id = r.situation_id',
'                       and e.domain_id = l_domain_id',
'                     order by e.occurred_at desc',
'                ) where rownum <= 20',
'            ) loop',
'                apex_json.open_object;',
'                apex_json.write(''signal_event_id'', uuid_text(er.signal_event_id));',
'                apex_json.write(''diagnostic_source_id'', uuid_text(er.diagnostic_source_id));',
'                apex_json.write(''source_event_key'', er.source_event_key);',
