'                apex_json.write(''summary'', er.summary);',
'                apex_json.write(''occurred_at'', utc_text(er.occurred_at));',
'                apex_json.close_object;',
'            end loop;',
'            apex_json.close_array;',
'',
'            apex_json.open_array(''run_ids'');',
'            for rr in (',
'                select ops_run_id',
'                  from kbot_ops_run',
'                 where situation_id = r.situation_id',
'                   and domain_id = l_domain_id',
'                 order by created_at desc',
'            ) loop',
'                apex_json.write(uuid_text(rr.ops_run_id));',
'            end loop;',
'            apex_json.close_array;',
'            apex_json.close_object;',
'        end loop;',
'    else',
unistr('        raise_application_error(-20003, ''\4E0D\652F\6301\7684\8BFB\53D6\7C7B\578B\3002'');'),
'    end if;',
'',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>wwv_flow_imp.id(48468648780834581)
,p_internal_uid=>48498540954836800
);
