,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('select display_name || ''\FF08'' || status || ''\FF09'' as display_value,'),
'       lower(',
'           substr(rawtohex(collection_id), 1, 8) || ''-'' ||',
'           substr(rawtohex(collection_id), 9, 4) || ''-'' ||',
'           substr(rawtohex(collection_id), 13, 4) || ''-'' ||',
'           substr(rawtohex(collection_id), 17, 4) || ''-'' ||',
'           substr(rawtohex(collection_id), 21, 12)',
'       ) as return_value',
'  from kbot_kc_collection',
' where domain_id = :P0_DOMAIN_ID',
'   and status = ''ACTIVE''',
'   and display_name = ''operations-manuals''',
'   and json_value(',
'           metadata_json,',
'           ''$.owner_app_id''',
