,p_source_type=>'ALWAYS_NULL'
,p_display_as=>'NATIVE_SELECT_MANY'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('select s.display_name || ''\FF08'' || s.source_type || '' \00B7 '' ||'),
unistr('       case when s.status = ''ENABLED'' then ''\5DF2\542F\7528'' else ''\5DF2\505C\7528\FF0C\4EC5\4FDD\7559\5DF2\6709\7ED1\5B9A'' end || ''\FF09'' as display_value,'),
'       lower(',
'           substr(rawtohex(s.diagnostic_source_id), 1, 8) || ''-'' ||',
'           substr(rawtohex(s.diagnostic_source_id), 9, 4) || ''-'' ||',
'           substr(rawtohex(s.diagnostic_source_id), 13, 4) || ''-'' ||',
'           substr(rawtohex(s.diagnostic_source_id), 17, 4) || ''-'' ||',
'           substr(rawtohex(s.diagnostic_source_id), 21, 12)',
'       ) as return_value',
'  from kbot_ops_diagnostic_source s',
' where s.domain_id = :P0_DOMAIN_ID',
'   and (',
'       s.status = ''ENABLED''',
'       or (',
'           :P77_AGENT_ID is not null',
'           and exists (',
'               select 1',
'                 from kbot_ops_agent a',
'                 join kbot_ops_agent_version_target avt',
'                   on avt.agent_version_id = a.current_version_id',
'                 join kbot_ops_target_source_binding tsb',
'                   on tsb.target_id = avt.target_id',
'                where a.domain_id = :P0_DOMAIN_ID',
'                  and a.agent_id = hextoraw(replace(:P77_AGENT_ID, ''-'', ''''))',
'                  and tsb.diagnostic_source_id = s.diagnostic_source_id',
'           )',
'       )',
'   )',
' order by case when s.status = ''ENABLED'' then 0 else 1 end,',
'          s.display_name'))
,p_colspan=>6
,p_label_alignment=>'RIGHT-CENTER'
,p_field_alignment=>'LEFT-CENTER'
,p_field_template=>1610598484065263269
,p_item_icon_css_classes=>'fa-heartbeat'
,p_item_template_options=>'#DEFAULT#'
