wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(48526407859836976)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P77_LOAD_CONTEXT'
,p_static_id=>'p77-load-context'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_agent_id varchar2(36) := trim(:P77_AGENT_ID);',
'    l_agent_raw raw(16);',
'begin',
'    if l_agent_id is not null then',
'        if not regexp_like(',
'            l_agent_id,',
'            ''^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$''',
'        ) then',
unistr('            raise_application_error(-20001, ''\667A\80FD\4F53 ID \683C\5F0F\65E0\6548\3002'');'),
'        end if;',
'        l_agent_raw := hextoraw(replace(l_agent_id, ''-'', ''''));',
'    end if;',
'',
'    apex_json.open_object;',
'    apex_json.open_array(''sources'');',
'    for r in (',
'        select lower(',
'                   substr(rawtohex(diagnostic_source_id), 1, 8) || ''-'' ||',
'                   substr(rawtohex(diagnostic_source_id), 9, 4) || ''-'' ||',
'                   substr(rawtohex(diagnostic_source_id), 13, 4) || ''-'' ||',
'                   substr(rawtohex(diagnostic_source_id), 17, 4) || ''-'' ||',
'                   substr(rawtohex(diagnostic_source_id), 21, 12)',
'               ) as source_id,',
'               display_name,',
'               status',
'          from kbot_ops_diagnostic_source',
'         where domain_id = :P0_DOMAIN_ID',
'         order by upper(display_name), diagnostic_source_id',
'    ) loop',
'        apex_json.open_object;',
'        apex_json.write(''source_id'', r.source_id);',
'        apex_json.write(''display_name'', r.display_name);',
'        apex_json.write(''status'', r.status);',
'        apex_json.close_object;',
'    end loop;',
'    apex_json.close_array;',
'',
'    apex_json.open_array(''targets'');',
'    for r in (',
'        select lower(',
'                   substr(rawtohex(target_id), 1, 8) || ''-'' ||',
'                   substr(rawtohex(target_id), 9, 4) || ''-'' ||',
'                   substr(rawtohex(target_id), 13, 4) || ''-'' ||',
'                   substr(rawtohex(target_id), 17, 4) || ''-'' ||',
'                   substr(rawtohex(target_id), 21, 12)',
'               ) as target_id,',
'               display_name,',
'               status,',
'               controlled_change_enabled',
'          from kbot_ops_target',
'         where domain_id = :P0_DOMAIN_ID',
'         order by upper(display_name), target_id',
'    ) loop',
'        apex_json.open_object;',
'        apex_json.write(''target_id'', r.target_id);',
'        apex_json.write(''display_name'', r.display_name);',
'        apex_json.write(''status'', r.status);',
'        apex_json.write(''controlled_change_enabled'', r.controlled_change_enabled = 1);',
'        apex_json.close_object;',
'    end loop;',
'    apex_json.close_array;',
'',
'    if l_agent_raw is not null then',
'        for r in (',
'            select lower(',
'                       substr(rawtohex(a.agent_id), 1, 8) || ''-'' ||',
'                       substr(rawtohex(a.agent_id), 9, 4) || ''-'' ||',
'                       substr(rawtohex(a.agent_id), 13, 4) || ''-'' ||',
'                       substr(rawtohex(a.agent_id), 17, 4) || ''-'' ||',
'                       substr(rawtohex(a.agent_id), 21, 12)',
'                   ) as agent_id,',
'                   a.display_name,',
'                   a.description,',
'                   a.status,',
'                   a.row_version,',
'                   json_serialize(v.models_json returning clob) as models_json,',
'                   json_serialize(v.image_capabilities_json returning clob) as image_capabilities_json,',
'                   v.instruction,',
'                   json_serialize(v.config_json returning clob) as config_json,',
'                   case json_value(p.rules_json, ''$.auto_alert_enabled'' returning varchar2)',
'                       when ''true'' then 1',
'                       when ''1'' then 1',
'                       else 0',
'                   end as auto_alert_enabled,',
'                   nvl(json_value(p.rules_json, ''$.auto_observe_min_severity'' returning varchar2), ''CRITICAL'') as min_severity,',
'                   nvl(json_value(p.rules_json, ''$.auto_observe_min_target_level'' returning number), 1) as min_target_level,',
'                   nvl(json_value(p.rules_json, ''$.alert_cooldown_seconds'' returning number), 900) / 60 as cooldown_minutes,',
'                   v.agent_version_id',
'              from kbot_ops_agent a',
'              join kbot_ops_agent_version v',
'                on v.agent_version_id = a.current_version_id',
'              left join kbot_ops_policy p',
'                on p.policy_id = v.policy_id',
'               and p.domain_id = a.domain_id',
'             where a.agent_id = l_agent_raw',
'               and a.domain_id = :P0_DOMAIN_ID',
'        ) loop',
'            apex_json.open_object(''agent'');',
'            apex_json.write(''agent_id'', r.agent_id);',
'            apex_json.write(''display_name'', r.display_name);',
'            apex_json.write(''description'', r.description);',
'            apex_json.write(''status'', r.status);',
'            apex_json.write(''row_version'', r.row_version);',
'            apex_json.write(''models_json'', r.models_json);',
'            apex_json.write(''image_capabilities_json'', r.image_capabilities_json);',
'            apex_json.write(''instruction'', r.instruction);',
'            apex_json.write(''config_json'', r.config_json);',
'            apex_json.write(''auto_alert_enabled'', r.auto_alert_enabled = 1);',
'            apex_json.write(''auto_observe_min_severity'', r.min_severity);',
'            apex_json.write(''auto_observe_min_target_level'', r.min_target_level);',
'            apex_json.write(''alert_cooldown_minutes'', r.cooldown_minutes);',
'            apex_json.open_array(''diagnostic_source_ids'');',
'            for x in (',
'                select lower(',
'                           substr(rawtohex(diagnostic_source_id), 1, 8) || ''-'' ||',
'                           substr(rawtohex(diagnostic_source_id), 9, 4) || ''-'' ||',
'                           substr(rawtohex(diagnostic_source_id), 13, 4) || ''-'' ||',
'                           substr(rawtohex(diagnostic_source_id), 17, 4) || ''-'' ||',
'                           substr(rawtohex(diagnostic_source_id), 21, 12)',
'                       ) as source_id',
'                  from (',
'                      select distinct tsb.diagnostic_source_id',
'                        from kbot_ops_agent_version_target avt',
'                        join kbot_ops_target_source_binding tsb',
'                          on tsb.target_id = avt.target_id',
'                       where avt.agent_version_id = r.agent_version_id',
'                         and tsb.status = ''ACTIVE''',
'                  )',
'                 order by diagnostic_source_id',
'            ) loop',
'                apex_json.write(x.source_id);',
'            end loop;',
'            apex_json.close_array;',
'            apex_json.open_array(''target_ids'');',
'            for x in (',
'                select lower(',
'                           substr(rawtohex(target_id), 1, 8) || ''-'' ||',
'                           substr(rawtohex(target_id), 9, 4) || ''-'' ||',
'                           substr(rawtohex(target_id), 13, 4) || ''-'' ||',
'                           substr(rawtohex(target_id), 17, 4) || ''-'' ||',
'                           substr(rawtohex(target_id), 21, 12)',
'                       ) as target_id',
'                  from kbot_ops_agent_version_target',
'                 where agent_version_id = r.agent_version_id',
'                 order by target_id',
'            ) loop',
'                apex_json.write(x.target_id);',
'            end loop;',
'            apex_json.close_array;',
'            apex_json.close_object;',
'        end loop;',
'    end if;',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>wwv_flow_imp.id(48468937883834581)
,p_internal_uid=>48526407859836976
);
end;
