,p_process_name=>'P101_GET_NAVIGATION_URL'
,p_static_id=>'p101-get-navigation-url'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_app_id  varchar2(64) := lower(v(''P0_AUTH_APP_ID''));',
'    l_page_id number;',
'begin',
'    l_page_id := 10;',
'',
'    if l_page_id is null or apex_application.g_x01 <> to_char(l_page_id) then',
unistr('        raise_application_error(-20001, ''\76EE\6807\5E94\7528\9996\9875\65E0\6548\3002'');'),
'    end if;',
'',
'    apex_json.open_object;',
'    apex_json.write(',
'        ''url'',',
'        apex_page.get_url(',
'            p_page        => l_page_id,',
'            p_clear_cache => to_char(l_page_id)',
'        )',
'    );',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>wwv_flow_imp.id(48471594459834621)
,p_internal_uid=>48534241549837268
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(48534128208837267)
,p_process_sequence=>4
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P101_LOAD_CREATION_CONTEXT'
,p_static_id=>'p101-load-creation-context'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_app_id    varchar2(64) := lower(v(''P0_AUTH_APP_ID''));',
'    l_domain_id number := to_number(v(''P0_DOMAIN_ID''));',
'',
'    function uuid_text(p_value raw) return varchar2 is',
'        l_hex varchar2(32) := rawtohex(p_value);',
'    begin',
'        return lower(',
'            substr(l_hex, 1, 8) || ''-'' || substr(l_hex, 9, 4) || ''-'' ||',
'            substr(l_hex, 13, 4) || ''-'' || substr(l_hex, 17, 4) || ''-'' ||',
'            substr(l_hex, 21, 12)',
'        );',
'    end;',
'begin',
'    if l_app_id <> ''aiops''',
'       or l_domain_id is null or l_domain_id <= 0 then',
unistr('        raise_application_error(-20001, ''\5F53\524D\5E94\7528\6216\4E1A\52A1\57DF\4E0A\4E0B\6587\65E0\6548\3002'');'),
'    end if;',
'',
'    apex_json.open_object;',
'    apex_json.open_array(''members'');',
'    for r in (',
'        select distinct pu.user_id,',
'               pu.display_name,',
'               pu.status',
'          from kbot_platform_user pu',
'          join kbot_app_member m',
'            on m.app_id = l_app_id',
'           and m.user_id = pu.user_id',
'           and m.status = ''ACTIVE''',
'          join kbot_app_member_role mr',
'            on mr.app_id = m.app_id',
'           and mr.user_id = m.user_id',
'           and mr.status = ''ACTIVE''',
'          join kbot_app_role_permission rp',
'            on rp.app_id = mr.app_id',
'           and rp.role_code = mr.role_code',
'           and rp.permission_code = l_app_id || '':use''',
'         where pu.status = ''ACTIVE''',
'           and (',
'               mr.scope_mode = ''ALL_APP_DOMAINS''',
'               or exists (',
'                   select 1',
'                     from kbot_app_member_role_scope rs',
'                    where rs.app_id = mr.app_id',
'                      and rs.user_id = mr.user_id',
'                      and rs.role_code = mr.role_code',
'                      and rs.domain_id = l_domain_id',
'               )',
'           )',
'         order by upper(nvl(pu.display_name, pu.user_id)), upper(pu.user_id)',
'    ) loop',
'        apex_json.open_object;',
'        apex_json.write(''user_id'', r.user_id);',
'        apex_json.write(''display_name'', r.display_name);',
'        apex_json.write(''status'', r.status);',
'        apex_json.open_array(''role_bindings'');',
'        apex_json.open_object;',
'        apex_json.write(''scope_mode'', ''SELECTED_DOMAINS'');',
'        apex_json.write(''status'', ''ACTIVE'');',
'        apex_json.open_array(''domain_ids'');',
'        apex_json.write(l_domain_id);',
'        apex_json.close_array;',
'        apex_json.close_object;',
'        apex_json.close_array;',
'        apex_json.close_object;',
'    end loop;',
'    apex_json.close_array;',
'',
'    apex_json.open_array(''agents'');',
'        for r in (',
'            select agent_id, display_name, description, status',
'              from kbot_ops_agent',
'             where domain_id = l_domain_id',
'               and status = ''ACTIVE''',
'             order by upper(display_name), agent_id',
'        ) loop',
'            apex_json.open_object;',
'            apex_json.write(''agent_id'', uuid_text(r.agent_id));',
'            apex_json.write(''display_name'', r.display_name);',
'            apex_json.write(''description'', r.description);',
'            apex_json.write(''status'', r.status);',
'            apex_json.close_object;',
'        end loop;',
'',
'    apex_json.close_array;',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>wwv_flow_imp.id(48471594459834621)
,p_internal_uid=>48534128208837267
);
end;
