wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(48535847449837268)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P108_LOAD_EFFECTIVE_ACCESS'
,p_static_id=>'p108-load-effective-access'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_agent_id     RAW(16);',
'    v_agent_text   VARCHAR2(64) := LOWER(TRIM(apex_application.g_x01));',
'    v_display_name kbot_ops_agent.display_name%TYPE;',
'    v_domain_id    kbot_ops_agent.domain_id%TYPE;',
'    v_domain_name  kbot_platform_domain.name%TYPE;',
'    v_status       kbot_ops_agent.status%TYPE;',
'BEGIN',
'    BEGIN',
'        v_agent_id := HEXTORAW(REPLACE(v_agent_text, ''-'', ''''));',
'    EXCEPTION',
'        WHEN OTHERS THEN',
unistr('            raise_application_error(-20001, ''\667A\80FD\4F53 ID \65E0\6548\3002'');'),
'    END;',
'',
'    BEGIN',
'        SELECT a.display_name, a.domain_id, d.name, a.status',
'          INTO v_display_name, v_domain_id, v_domain_name, v_status',
'          FROM kbot_ops_agent a',
'          JOIN kbot_platform_domain d ON d.domain_id = a.domain_id',
'         WHERE a.agent_id = v_agent_id',
'           AND a.domain_id = TO_NUMBER(:P0_DOMAIN_ID);',
'    EXCEPTION',
'        WHEN NO_DATA_FOUND THEN',
unistr('            raise_application_error(-20002, ''\5F53\524D\4E1A\52A1\57DF\4E2D\4E0D\5B58\5728\8BE5\667A\80FD\4F53\3002'');'),
'    END;',
'',
'    apex_json.open_object;',
'    apex_json.open_object(''agent'');',
'    apex_json.write(''agent_id'', v_agent_text);',
'    apex_json.write(''display_name'', v_display_name);',
'    apex_json.write(''domain_id'', v_domain_id);',
'    apex_json.write(''domain_name'', v_domain_name);',
'    apex_json.write(''status'', v_status);',
'    apex_json.close_object;',
'    apex_json.open_array(''members'');',
'    FOR m IN (',
'        SELECT DISTINCT u.user_id, u.display_name, r.display_name role_name, mr.role_code',
'          FROM kbot_app_member am',
'          JOIN kbot_platform_user u ON u.user_id = am.user_id AND u.status = ''ACTIVE''',
'          JOIN kbot_app_member_role mr ON mr.app_id = am.app_id AND mr.user_id = am.user_id AND mr.status = ''ACTIVE''',
'          JOIN kbot_app_role r ON r.app_id = mr.app_id AND r.role_code = mr.role_code AND r.status = ''ACTIVE''',
'         WHERE v_status = ''ACTIVE''',
'           AND am.app_id = ''aiops''',
'           AND am.status = ''ACTIVE''',
'           AND (',
'               mr.scope_mode = ''ALL_APP_DOMAINS''',
'               OR EXISTS (',
'                   SELECT 1 FROM kbot_app_member_role_scope rs',
'                    WHERE rs.app_id = mr.app_id',
'                      AND rs.user_id = mr.user_id',
'                      AND rs.role_code = mr.role_code',
'                      AND rs.domain_id = v_domain_id',
'               )',
'           )',
'         ORDER BY UPPER(u.display_name), u.user_id',
'    ) LOOP',
'        apex_json.open_object;',
'        apex_json.write(''user_id'', m.user_id);',
'        apex_json.write(''display_name'', m.display_name);',
'        apex_json.write(''role_code'', m.role_code);',
'        apex_json.write(''role_name'', m.role_name);',
'        apex_json.close_object;',
'    END LOOP;',
'    apex_json.close_array;',
'    apex_json.close_object;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>wwv_flow_imp.id(48468937883834581)
,p_internal_uid=>48535847449837268
);
end;
