,p_name=>unistr('\5DE1\68C0\6267\884C')
,p_static_id=>'p112-fire-report'
,p_region_name=>'p112-fire-report'
,p_parent_plug_id=>wwv_flow_imp.id(48538567327837354)
,p_template=>4073835273271169698
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--horizontalBorders'
,p_grid_column_span=>6
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select lower(substr(rawtohex(f.inspection_fire_id), 1, 8) || ''-'' ||',
'             substr(rawtohex(f.inspection_fire_id), 9, 4) || ''-'' ||',
'             substr(rawtohex(f.inspection_fire_id), 13, 4) || ''-'' ||',
'             substr(rawtohex(f.inspection_fire_id), 17, 4) || ''-'' ||',
'             substr(rawtohex(f.inspection_fire_id), 21, 12)) as fire_id,',
unistr('       to_char(f.scheduled_for at local, ''YYYY-MM-DD HH24:MI'') || '' \6267\884C'' as fire_label,'),
'       p.display_name as plan_name,',
'       f.status,',
'       to_char(f.completed_count) || '' / '' || to_char(f.target_count) as completion_progress,',
'       f.failed_count,',
'       f.scheduled_for',
'  from kbot_ops_inspection_fire f',
'  join kbot_ops_inspection_plan p',
'    on p.inspection_plan_id = f.inspection_plan_id',
' where p.domain_id = :P0_DOMAIN_ID',
'   and (:P112_PLAN_FILTER is null',
'        or p.display_name = :P112_PLAN_FILTER)',
'   and (:P112_TARGET_FILTER is null',
'        or exists (',
'            select 1',
'              from kbot_ops_run r',
'             where r.inspection_fire_id = f.inspection_fire_id',
'               and r.domain_id = p.domain_id',
'               and exists (',
'                   select 1',
'                     from kbot_ops_target rt',
'                    where rt.target_id = r.target_id',
'                      and rt.domain_id = r.domain_id',
'                      and rt.display_name = :P112_TARGET_FILTER',
'               )',
'        ))',
'   and (:P112_STATUS_FILTER is null',
'        or f.status = :P112_STATUS_FILTER)',
'   and (:P112_SCHEDULED_DATE_FILTER is null',
'        or trunc(cast(f.scheduled_for at local as date)) =',
'           to_date(:P112_SCHEDULED_DATE_FILTER, ''YYYY-MM-DD''))',
' order by f.created_at desc,',
'          f.inspection_fire_id desc'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P0_DOMAIN_ID,P112_PLAN_FILTER,P112_TARGET_FILTER,P112_STATUS_FILTER,P112_SCHEDULED_DATE_FILTER'
