,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P127_GET_CHAT_URL'
,p_static_id=>'p127-get-chat-url'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_agent_id varchar2(64) := lower(trim(apex_application.g_x01));',
'begin',
'    if not regexp_like(l_agent_id, ''^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'') then',
unistr('        raise_application_error(-20001, ''\667A\80FD\4F53 ID \65E0\6548\3002'');'),
'    end if;',
'    apex_json.open_object;',
'    apex_json.write(',
'        ''url'',',
'        apex_page.get_url(',
'            p_page        => 21,',
'            p_clear_cache => ''21'',',
'            p_items       => ''P0_DOMAIN_ID,P21_AGENT_ID,P21_AGENT_SCOPE'',',
'            p_values      => :P0_DOMAIN_ID || '','' || l_agent_id || '',aiops''',
'        )',
'    );',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>wwv_flow_imp.id(48468648780834581)
,p_internal_uid=>54341556567342427
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(54398009004563396)
,p_process_sequence=>5
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'P127_LOAD_AGENT_TIMES'
,p_static_id=>'p127-load-agent-times'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    apex_json.open_object;',
'    apex_json.open_array(''items'');',
'',
'    for r in (',
'        select lower(',
'                   substr(rawtohex(a.agent_id), 1, 8) || ''-'' ||',
'                   substr(rawtohex(a.agent_id), 9, 4) || ''-'' ||',
'                   substr(rawtohex(a.agent_id), 13, 4) || ''-'' ||',
'                   substr(rawtohex(a.agent_id), 17, 4) || ''-'' ||',
'                   substr(rawtohex(a.agent_id), 21, 12)',
'               ) as agent_id,',
'               to_char(',
'                   a.created_at,',
'                   ''YYYY-MM-DD"T"HH24:MI:SS.FF3TZH:TZM''',
'               ) as created_at',
'          from kbot_ops_agent a',
'         where a.domain_id = :P0_DOMAIN_ID',
'           and a.status = ''ACTIVE''',
'    ) loop',
'        apex_json.open_object;',
'        apex_json.write(''agent_id'', r.agent_id);',
'        apex_json.write(''created_at'', r.created_at);',
'        apex_json.close_object;',
'    end loop;',
'',
'    apex_json.close_array;',
'    apex_json.close_object;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_security_scheme=>wwv_flow_imp.id(48468648780834581)
,p_internal_uid=>54398009004563396
);
end;
